#
# Uzytkownik: "nie masz w logach co wysylamy, dodaj jeszcze to do
# logow, co wysylane jest do kazdego z agentow".
#
# Ma racje i to byla realna dziura. Kazda naprawa od v308 do v312
# wyszla z tego, ze RECZNIE wklejal mi wiadomosc, ktora zobaczyl u
# Kamila na stronie — bo w naszych wlasnych logach byla tylko jej
# DLUGOSC. Nie bylo widac ani czterech zawolan sklejonych w jedna
# linie, ani zdublowanego akapitu Wojtka.
#
# Tresc idzie do pliku zdarzen biegu (.jsonl) przy kazdej wysylce
# — patrz deepseek(). Tutaj jest jej czytnik, i celowo stoi PRZED
# reszta importow: zeby przeczytanie wlasnych wysylek nie wymagalo
# ani jednej biblioteki bota.
#
#     python3 agent.py --wyslane <plik.jsonl> [Kamil] [krok]

_IMIONA_ROL = {
    "PLANNER": "Tomek",
    "RESEARCHER": "Kamil",
    "ENGINEER": "Bartek",
    "CRITIC": "Marek",
    "BROWSER": "Ola",
    "WOJTEK": "Wojtek",
    "MAIN": "MAIN",
    "PROGRESS_ESTIMATOR": "Ela",
    "CODE_REVIEWER": "Piotr",
    "CODE_FIXER": "Ania",
}


def wypisz_wyslane(plik, rola=None, krok=None):
    """
    Wypisuje slowo w slowo to, co poszlo do agentow.

    rola: "Kamil" albo "RESEARCHER" — jedno i drugie.
    krok: numer kroku, gdy interesuje tylko jeden.
    """

    szukane = None

    if rola:
        szukane = str(rola).upper()

        for klucz, imie in _IMIONA_ROL.items():
            if imie.upper() == szukane:
                szukane = klucz
                break

    with open(plik, encoding="utf-8") as f:

        for linia in f:

            try:
                wpis = json.loads(linia)
            except Exception:
                continue

            if wpis.get("typ") != "prompt" or "tresc" not in wpis:
                continue

            if szukane and str(wpis.get("rola", "")).upper() != szukane:
                continue

            if krok is not None and wpis.get("krok") != krok:
                continue

            print("=" * 60)
            print("krok %s \u2192 %s (%s znak\u00f3w)" % (
                wpis.get("krok"),
                _IMIONA_ROL.get(wpis.get("rola"), wpis.get("rola")),
                wpis.get("znaki")
            ))
            print("=" * 60)
            print(wpis["tresc"])
            print()


def wypisz_wykonane(plik, krok=None):
    """
    Co Gemini naprawde uruchomilo i co z tego wyszlo (v317).

    W terminalu wynik narzedzia jest przyciety do 1000 znakow, wiec
    z samego logu nie dalo sie sprawdzic nawet tego, czy dwa
    identycznie wygladajace wyniki to bylo to samo polecenie.
    """

    ostatnie = None

    with open(plik, encoding="utf-8") as f:

        for linia in f:

            try:
                wpis = json.loads(linia)
            except Exception:
                continue

            if wpis.get("typ") not in ("narzedzie", "wynik"):
                continue

            if krok is not None and wpis.get("krok") != krok:
                continue

            if wpis.get("typ") == "narzedzie":
                ostatnie = wpis
                continue

            print("=" * 60)
            print("krok %s \u2192 %s  %s" % (
                wpis.get("krok"),
                wpis.get("nazwa"),
                "OK" if wpis.get("ok") else "B\u0141\u0104D"
            ))

            if ostatnie:
                _a = ostatnie.get("argumenty")

                if isinstance(_a, dict):
                    for _k, _v in _a.items():
                        print("  %s: %s" % (_k, _v))

                elif _a is not None:
                    print("  " + str(_a))

            print("-" * 60)
            print(json.dumps(
                wpis.get("wynik"), ensure_ascii=False,
                indent=2, default=str
            ))
            print()

            ostatnie = None


def wypisz_rozmowe(plik, rola=None, krok=None):
    """
    Rozmowa z jedna osoba: co poszlo i co wrocilo, po kolei (v320).

    To jest widok, ktorego brakowalo najbardziej. Wysylki i
    odpowiedzi lezaly w pliku osobno, wiec zeby zobaczyc JEDNA ture
    trzeba bylo przeskakiwac miedzy nimi. Tutaj stoja obok siebie,
    razem z czasem, statusem i tym, czy odpowiedz jest z szarego
    tekstu.
    """

    szukane = None

    if rola:
        szukane = str(rola).upper()

        for klucz, imie in _IMIONA_ROL.items():
            if imie.upper() == szukane:
                szukane = klucz
                break

    with open(plik, encoding="utf-8") as f:

        for linia in f:

            try:
                wpis = json.loads(linia)
            except Exception:
                continue

            if wpis.get("typ") not in ("prompt", "odpowiedz"):
                continue

            if szukane and str(wpis.get("rola", "")).upper() != szukane:
                continue

            if krok is not None and wpis.get("krok") != krok:
                continue

            imie = _IMIONA_ROL.get(wpis.get("rola"), wpis.get("rola"))

            if wpis.get("typ") == "prompt":
                print("=" * 60)
                print("krok %s  \u2192 %s  (%s znak\u00f3w)" % (
                    wpis.get("krok"), imie, wpis.get("znaki")
                ))
                print("=" * 60)

            else:
                uwagi = []

                if wpis.get("urwane"):
                    uwagi.append("URWANE")

                if wpis.get("z_myslenia"):
                    uwagi.append("z szarego tekstu")

                if wpis.get("samo_myslenie"):
                    uwagi.append(
                        "samo my\u015blenie: "
                        + str(wpis.get("samo_myslenie"))
                    )

                _st = str(wpis.get("status") or "")

                if _st and _st.upper() != "FINISHED":
                    uwagi.append("status " + _st)

                print("-" * 60)
                print("%s \u2192  (%s znak\u00f3w, %ss, konto %s)%s" % (
                    imie,
                    wpis.get("znaki"),
                    wpis.get("sekundy"),
                    wpis.get("konto"),
                    ("  [" + ", ".join(uwagi) + "]") if uwagi else ""
                ))
                print("-" * 60)

            print(wpis.get("tresc", ""))
            print()


if len(sys.argv) > 2 and sys.argv[1] == "--rozmowa":
    wypisz_rozmowe(
        sys.argv[2],
        sys.argv[3] if len(sys.argv) > 3 else None,
        int(sys.argv[4]) if len(sys.argv) > 4 else None
    )
    raise SystemExit(0)


if len(sys.argv) > 2 and sys.argv[1] == "--wyslane":
    wypisz_wyslane(
        sys.argv[2],
        sys.argv[3] if len(sys.argv) > 3 else None,
        int(sys.argv[4]) if len(sys.argv) > 4 else None
    )
    raise SystemExit(0)


if len(sys.argv) > 2 and sys.argv[1] == "--wykonane":
    wypisz_wykonane(
        sys.argv[2],
        int(sys.argv[3]) if len(sys.argv) > 3 else None
    )
    raise SystemExit(0)


