def now():
    return datetime.now().strftime("%H:%M:%S")


def zacznij_zapis_biegu(cel=""):
    """
    Otwiera pliki tego biegu. Nazwa to data i godzina startu, wiec
    kolejne uruchomienia nie nadpisuja sie nawzajem.
    """

    global _plik_przebiegu, _plik_zdarzen, _biezacy_krok

    _biezacy_krok = 0

    try:
        PRZEBIEG_DIR.mkdir(parents=True, exist_ok=True)

        stempel = datetime.now().strftime("%Y%m%d_%H%M%S")

        _plik_przebiegu = PRZEBIEG_DIR / (stempel + ".log")
        _plik_zdarzen = PRZEBIEG_DIR / (stempel + ".jsonl")

        _plik_przebiegu.write_text(
            "CEL: " + str(cel or "").strip() + "\n\n",
            encoding="utf-8"
        )
        _plik_zdarzen.write_text("", encoding="utf-8")

        zapisz_zdarzenie("start", cel=str(cel or "").strip())

    except Exception:
        # Brak miejsca albo praw — zapis jest pomocniczy i nigdy
        # nie moze wywrocic samego biegu.
        _plik_przebiegu = None
        _plik_zdarzen = None


# Co ile krokow pokazujemy liczby. Rzadziej niz co krok, bo to
# ma byc przeglad, a nie kolejna sciana w logu.
_CO_ILE_PODSUMOWANIE = 5


def ustaw_krok(numer):
    """Od tej chwili wszystko, co zapisujemy, nalezy do tego kroku."""

    global _biezacy_krok

    try:
        poprzedni = _biezacy_krok
        _biezacy_krok = int(numer)
    except (TypeError, ValueError):
        return

    # v342: log z terminala nalezy do kroku, w ktorym padl. Autor
    # dostaje go raz, przy najblizszej swojej turze — patrz
    # _log_dla_autora().
    #
    # v393: "najblizsza jego tura" jest W NASTEPNYM KROKU, a my
    # czyscilismy te liste na jego poczatku — czyli zanim ktokolwiek
    # zdazyl ja przeczytac.
    #
    # KOLEJNOSC W KROKU, odczytana z kazdego logu: najpierw pytamy
    # zespol (Ola, Wojtek, Kamil, Tomek, Bartek, Marek, MAIN), a
    # DOPIERO POTEM Gemini uruchamia narzedzia. Uruchomienia kroku N
    # powstaja wiec po naradzie kroku N, a narada kroku N+1 zastawala
    # juz pusta liste.
    #
    # ZMIERZONE: blok "moj_log" pojawil sie 2 razy w 50 biegach — i
    # to tylko u Ani, bo CODE_REVIEWER i CODE_FIXER sa pytani PO
    # uruchomieniach, w tym samym kroku. Bartek, ktory pisze
    # wiekszosc kodu, ani razu nie zobaczyl, co jego kod wypisal.
    #
    # Zostawiamy wiec uruchomienia z kroku, ktory wlasnie sie
    # skonczyl — to jedyna chwila, w ktorej ich autor moze je
    # przeczytac. Starsze odpadaja, wiec lista nie rosnie.
    if _biezacy_krok != poprzedni:

        _z_ostatniego_kroku = [
            u for u in _uruchomienia_kroku
            if u.get("krok") == poprzedni
        ]

        del _uruchomienia_kroku[:]
        _uruchomienia_kroku.extend(_z_ostatniego_kroku)

        del _przybylo_w_kroku[:]
        _kod_polozony_w_kroku.clear()

    zapisz_zdarzenie("krok")

    if (
        poprzedni
        and _biezacy_krok > poprzedni
        and poprzedni % _CO_ILE_PODSUMOWANIE == 0
    ):
        pokaz_podsumowanie_biegu()

    # v323: kopia na telefon po KAZDYM kroku, nie co piaty.
    #
    # Bieg 2026-09-12 21:02 skonczyl sie tak, ze system ubil calego
    # Termuksa w trakcie budowania APK. Przy zabiciu nie wykonuje sie
    # nic — ani nasze sprzatanie z v320, ani atexit. Zostaje to, co
    # bylo skopiowane wczesniej, czyli stan sprzed pieciu krokow.
    #
    # Kopiowanie dwoch plikow trwa tyle, co nic, a bieg i tak wlasnie
    # przeszedl do nastepnego kroku.
    elif poprzedni and _biezacy_krok > poprzedni:
        skopiuj_przebieg_na_telefon()


def skopiuj_przebieg_na_telefon():
    """
    Kopia obu plikow tam, gdzie widzi je Android.

    Zrodlem prawdy zostaje ~/agent/memory/przebieg — tam pisze sam
    agent i tam nic nie moze zniknac. To jest tylko kopia do
    wyciagniecia z telefonu, odswiezana razem z podsumowaniem.

    Cicha, gdy nie ma dostepu do pamieci wspoldzielonej: brak
    `termux-setup-storage` nie moze byc powodem, zeby cokolwiek w
    biegu poszlo nie tak.
    """

    if _plik_przebiegu is None:
        return ""

    zrodlo = HOME / "storage" / "shared"

    if not zrodlo.exists():
        return ""

    try:
        PRZEBIEG_NA_TELEFONIE.mkdir(parents=True, exist_ok=True)

        skopiowane = []

        for plik in (_plik_przebiegu, _plik_zdarzen):

            if plik is None or not plik.exists():
                continue

            cel = PRZEBIEG_NA_TELEFONIE / plik.name

            cel.write_bytes(plik.read_bytes())

            skopiowane.append(cel)

        if not skopiowane:
            return ""

        return str(PRZEBIEG_NA_TELEFONIE)

    except Exception:
        return ""


# v320: przy ktorym kroku ostatnio pokazalismy liczby — zeby przy
# wyjsciu nie powtarzac tego samego ekranu.
_krok_ostatniego_podsumowania = None


def pokaz_podsumowanie_biegu():
    """Liczby tego biegu — na ekran i do przebiegu."""

    global _krok_ostatniego_podsumowania

    tekst = podsumowanie_biegu()

    if not tekst:
        return

    _krok_ostatniego_podsumowania = _biezacy_krok

    ramka = (
        "\n" + "=" * 60
        + "\n  JAK IDZIE KOMUNIKACJA (liczone przez Pythona, "
        "bez pytania nikogo)\n"
        + "=" * 60 + "\n"
        + tekst + "\n"
        + "=" * 60
    )

    print(ramka)
    dopisz_do_przebiegu(ramka)

    gdzie = skopiuj_przebieg_na_telefon()

    if gdzie:
        print("  Kopia do wyciągnięcia z telefonu: " + gdzie)
    elif _plik_przebiegu is not None:
        print(
            "  Zapis biegu: " + str(_plik_przebiegu.parent)
            + "  (żeby mieć to widoczne z Androida: "
            "termux-setup-storage)"
        )



def _podsumuj_na_wyjsciu():
    """
    Liczby i kopia na telefon TAKZE wtedy, gdy program konczy sie
    Ctrl+C albo bledem (v320).

    Uzytkownik: "bo aktualizujesz po chyba 5 seriach, albo ja
    zatrzymuje — po zamknieciu tez zrob aktualizacje, jak docisne
    Ctrl+C".

    Ma racje: podsumowanie szlo co piaty krok, wiec bieg przerwany
    w kroku 8 zostawial liczby z kroku 5 i kopie przebiegu sprzed
    trzech krokow. Wlasnie tak wygladaly dwa ostatnie logi, ktore
    dostalem — urwane w polowie, bez koncowki.

    Nigdy nie rzuca: to jest sprzatanie po robocie, nie robota.
    """

    try:

        if _plik_przebiegu is None:
            return

        if _krok_ostatniego_podsumowania != _biezacy_krok:
            pokaz_podsumowanie_biegu()
            return

        # Liczby sa juz aktualne, ale kopia na telefonie moze byc
        # starsza o kilka linii — odswiezamy ja mimo wszystko.
        gdzie = skopiuj_przebieg_na_telefon()

        if gdzie:
            print("  Kopia do wyciągnięcia z telefonu: " + gdzie)

    except Exception:
        pass


atexit.register(_podsumuj_na_wyjsciu)


def dopisz_do_przebiegu(linia):

    if _plik_przebiegu is None:
        return

    try:
        with open(_plik_przebiegu, "a", encoding="utf-8") as f:
            f.write(str(linia).rstrip() + "\n")
    except Exception:
        pass


def _poczatek_bloku(block, ile=90):
    """
    Kilkadziesiat pierwszych znakow bloku, w jednej linii.

    Rozmiar mowi ILE poszlo, ale nie CO. Bez tego nie da sie
    odpowiedziec na pytanie "czy sondy po plikach powtarzaja te same
    listingi" — a to wlasnie takie pytania decyduja, co warto ciac.
    Kilkadziesiat znakow starcza, zeby rozpoznac powtorke, i nie
    rozdyma pliku.
    """

    return " ".join(str(block or "").split())[:ile]


def zapisz_zdarzenie(typ, **pola):
    """
    Jedno zdarzenie w formacie, ktory da sie policzyc — po jednym
    JSON-ie na linie. Nigdy nie rzuca: to jest notatnik obok
    roboty, nie sama robota.
    """

    if _plik_zdarzen is None:
        return

    try:
        wpis = {"krok": _biezacy_krok, "typ": str(typ)}
        wpis.update(pola)

        with open(_plik_zdarzen, "a", encoding="utf-8") as f:
            f.write(
                json.dumps(wpis, ensure_ascii=False, default=str)
                + "\n"
            )
    except Exception:
        pass


# ============================================================
# CZUJNIK: LICZBY, NIE OPINIE (v279)
# ============================================================
#
# Wszystko ponizej liczy sam Python, z pliku zdarzen — ZERO
# wywolan do DeepSeeka i Gemini. To jest ta czesc, ktora ma
# chodzic zawsze, bo nic nie kosztuje.
#
# Mierzymy dokladnie te rzeczy, ktore w tej sesji okazaly sie
# realnymi awariami, a byly widoczne dopiero wtedy, gdy uzytkownik
# recznie wkleil kawalek ekranu:
#
#   - ile znakow poszlo do ktorej roli (spam w promptach),
#   - z jakich blokow to bylo (co konkretnie ciac),
#   - ile bramka _only_if_new realnie oszczedzila,
#   - kroki, w ktorych nie padlo ANI JEDNO wywolanie narzedzia
#     (narada mielila, robota stala),
#   - zdania typu "urwales", "nie widze", "nie mam" — czyli
#     moment, w ktorym ktos NIE DOSTAL tego, co mial dostac.

# Ktos mowi wprost, ze czegos nie dostal. To najtansza i
# najpewniejsza oznaka zepsutej komunikacji, jaka mamy: nie
# domysl, tylko cytat.
_NIE_DOSTAL_RE = re.compile(
    # v319: samo "ucięt" łapało rozmowy O DANYCH, nie o
    # wiadomościach. Log 2026-09-12, krok 6 — Marek pisał o
    # cudzysłowach w sed: "regex złapie ucięty string", a czujnik
    # zgłosił to jako "ktoś nie dostał tego, co miał dostać".
    # Musi więc paść przy tym słowo o WYPOWIEDZI — w tę albo w
    # tamtą stronę ("ucięta odpowiedź", "plan jest ucięty").
    r"urwa[łl]e[śs]|urywa\s+si[eę]|"
    r"uci[eę]t\w*\s+(?:\w+\s+){0,2}"
    r"(?:wiadomo|odpowied|wypowied|plan|tekst|zdani|list|tre[śs])|"
    r"(?:wiadomo|odpowied|wypowied|plan|tekst|zdani|list|tre[śs])"
    r"\w*\s+(?:\w+\s+){0,2}(?:jest\s+)?uci[eę]t|"
    # v286: samo "nie widze" to za malo — Marek napisal "nie widze
    # blokerow", czyli POCHWALE, a czujnik zglosil to jako brak.
    # Musi paść, CZEGO nie widzi.
    r"nie\s+widz[eę]\s+(?:tego|tych|kodu|b[łl][eę]du|tre[śs]ci|"
    r"wiadomo[śs]ci|fragmentu|danych|wynik|nic\b|"
    r"[żz]adnego|[żz]adnych|w\s+[Tt]wojej)|"
    r"nie\s+mam\s+(?:tego|tych|dost[eę]pu|kodu)|"
    r"nie\s+do[łl][aą]czy[łl]e[śs]|"
    r"nie\s+znalaz[łl]em\s+w\s+(?:twojej|Twojej)\s+wiadomo|"
    r"podaj\s+mi\s+je|brakuje\s+(?:tresci|treści|fragmentu)",
    re.IGNORECASE
)


def _wczytaj_zdarzenia(sciezka):
    """Zdarzenia jednego biegu. Zepsute linie po prostu pomijamy."""

    zdarzenia = []

    try:
        with open(sciezka, encoding="utf-8") as f:
            for linia in f:
                linia = linia.strip()
                if not linia:
                    continue
                try:
                    zdarzenia.append(json.loads(linia))
                except Exception:
                    continue
    except Exception:
        return []

    return zdarzenia


def policz_bieg(sciezka=None):
    """
    Liczby jednego biegu. Zwraca slownik — nic nie drukuje, zeby
    dalo sie tego uzyc i do wyswietlenia, i do porownania biegow.
    """

    sciezka = sciezka or _plik_zdarzen

    if not sciezka:
        return {}

    zdarzenia = _wczytaj_zdarzenia(sciezka)

    if not zdarzenia:
        return {}

    wynik = {
        "cel": "",
        "kroki": 0,
        "do_roli": {},          # rola -> znaki lacznie
        "pytan_do_roli": {},    # rola -> ile razy pytana
        "bloki": {},            # (rola, blok) -> znaki
        "oszczedzone": 0,       # ile _only_if_new nie wyslalo
        "narzedzia": 0,
        "kroki_bez_narzedzia": [],
        "nie_dostal": [],       # (krok, rola) — ktos zglosil brak
    }

    narzedzia_w_kroku = {}
    kroki = set()

    for z in zdarzenia:

        typ = z.get("typ")
        krok = z.get("krok") or 0
        rola = str(z.get("rola") or "")
        znaki = int(z.get("znaki") or 0)

        if krok:
            kroki.add(krok)

        if typ == "start":
            wynik["cel"] = str(z.get("cel") or "")

        elif typ == "prompt":
            wynik["do_roli"][rola] = (
                wynik["do_roli"].get(rola, 0) + znaki
            )
            wynik["pytan_do_roli"][rola] = (
                wynik["pytan_do_roli"].get(rola, 0) + 1
            )

        elif typ == "blok":
            klucz = rola + "/" + str(z.get("co") or "")
            wynik["bloki"][klucz] = (
                wynik["bloki"].get(klucz, 0) + znaki
            )

        elif typ == "blok_powtorka":
            wynik["oszczedzone"] += znaki

        elif typ == "narzedzie":
            wynik["narzedzia"] += 1
            narzedzia_w_kroku[krok] = (
                narzedzia_w_kroku.get(krok, 0) + 1
            )

        elif typ == "wypowiedz":
            # Czy ktos wprost powiedzial, ze czegos nie dostal.
            pass

    wynik["kroki"] = len(kroki)

    wynik["kroki_bez_narzedzia"] = sorted(
        k for k in kroki if not narzedzia_w_kroku.get(k)
    )

    return wynik


# Linia, ktora wypisal sam Python: "[13:30:24] [krok 3] [TAG] ...".
_LINIA_LOGU_RE = re.compile(
    r"^\[\d{2}:\d{2}:\d{2}\]\s*\[krok\s+\d+\]\s*\["
)


def znajdz_zgloszone_braki(sciezka_przebiegu=None):
    """
    Miejsca, w ktorych ktos napisal wprost, ze czegos nie dostal.

    Czytamy z PRZEBIEGU, nie ze zdarzen — bo tam jest tresc
    wypowiedzi, a nie tylko jej dlugosc.
    """

    sciezka_przebiegu = sciezka_przebiegu or _plik_przebiegu

    if not sciezka_przebiegu:
        return []

    znaleziska = []
    krok = 0
    kto = ""

    # v286: przebieg zawiera TAKZE nasze wlasne podsumowania (patrz
    # pokaz_podsumowanie_biegu), a w nich cytaty z wczesniejszych
    # znalezisk. Bez tego czujnik znajdowal sam siebie i ten sam
    # cytat wracal przy kazdym kolejnym podsumowaniu.
    w_podsumowaniu = False

    # v390: przebieg zawiera teraz takze CALE wiadomosci, ktore
    # wyslalismy (patrz _wyslano). W nich siedza cytowane wypowiedzi
    # kolegow, wiec bez pominiecia tych blokow czujnik znajdowalby
    # kazda skarge po raz drugi — i przypisywal ja nie temu, kto ja
    # napisal, tylko temu, komu ja przekazalismy.
    w_wyslanym = False

    try:
        with open(sciezka_przebiegu, encoding="utf-8") as f:
            for linia in f:

                if linia.startswith(_RAMKA_WYSLANE):
                    w_wyslanym = True
                    continue

                if linia.startswith(_RAMKA_WYSLANE_KONIEC):
                    w_wyslanym = False
                    continue

                if w_wyslanym:
                    continue

                if "JAK IDZIE KOMUNIKACJA" in linia:
                    w_podsumowaniu = True
                    continue

                if linia.startswith("--- "):
                    w_podsumowaniu = False

                if w_podsumowaniu:
                    continue

                if linia.startswith("--- KROK "):
                    try:
                        krok = int(linia.split()[2])
                    except (IndexError, ValueError):
                        pass
                    continue

                if linia.startswith("--- ") and "(" in linia:
                    kto = linia[4:].split("(")[0].strip()
                    continue

                # v299: wlasny log Pythona to nie jest skarga roli.
                #
                # ZAOBSERWOWANY REALNY PRZYPADEK (log 2026-09-11).
                # Czujnik zameldowal: "Ktos zglosil, ze czegos nie
                # dostal: krok 3, Marek: [13:30:24] [krok 3]
                # [DEEPSEEK] MAIN: odpowiedz wyglada na ucieta".
                # To nie Marek — to nasza wlasna notatka o odpowiedzi
                # DeepSeeka, ktora akurat lezala pod naglowkiem
                # Marka. Czujnik sluzy do znajdowania problemow;
                # falszywy alarm w nim jest gorszy niz jego brak, bo
                # wysyla na bezdroza.
                if _LINIA_LOGU_RE.match(linia):
                    continue

                m = _NIE_DOSTAL_RE.search(linia)

                if m:
                    znaleziska.append({
                        "krok": krok,
                        "kto": kto,
                        "cytat": linia.strip()[:200]
                    })
    except Exception:
        return []

    return znaleziska


def podsumowanie_biegu(sciezka=None, sciezka_przebiegu=None):
    """Te same liczby, ulozone w kilka linijek do przeczytania."""

    dane = policz_bieg(sciezka)

    if not dane:
        return ""

    linie = [
        "Kroków: " + str(dane["kroki"])
        + ", wywołań narzędzi: " + str(dane["narzedzia"])
    ]

    # v300: ile zeszło z kont DeepSeeka w ostatniej godzinie. To jest
    # liczba, od ktorej zalezy, czy uzytkownik zobaczy limit strony —
    # wiec ma byc widoczna razem z reszta, a nie dopiero wtedy, gdy
    # bedzie za pozno.
    for _konto in sorted(_deepseek_wyslane):

        _uzyte = len(_posprzataj_okno(_konto, time.time()))

        if not _uzyte:
            continue

        linie.append(
            "Konto DeepSeek " + str(_konto) + ": " + str(_uzyte)
            + " wiadomości w ostatniej godzinie z "
            + str(_budzet_konta_teraz(_konto))
            + " (zostaje " + str(_budzet_konta(_konto))
            + " dla nas, " + str(DEEPSEEK_REZERWA_DLA_CZLOWIEKA)
            + " dla Ciebie)."
        )

    if dane["kroki_bez_narzedzia"]:
        linie.append(
            "Kroki bez ani jednego narzędzia: "
            + ", ".join(str(k) for k in dane["kroki_bez_narzedzia"])
        )

    for rola, znaki in sorted(
        dane["do_roli"].items(), key=lambda x: -x[1]
    ):
        razy = dane["pytan_do_roli"].get(rola, 0) or 1
        linie.append(
            "  " + rola.ljust(20) + str(znaki).rjust(8)
            + " znaków w " + str(razy) + " wiadomościach"
            + " (średnio " + str(znaki // razy) + ")"
        )

    if dane["bloki"]:
        linie.append("Najcięższe bloki:")
        for klucz, znaki in sorted(
            dane["bloki"].items(), key=lambda x: -x[1]
        )[:8]:
            linie.append("  " + klucz.ljust(28) + str(znaki).rjust(8))

    if dane["oszczedzone"]:
        linie.append(
            "Powtórek nie wysłano: " + str(dane["oszczedzone"])
            + " znaków"
        )

    braki = znajdz_zgloszone_braki(sciezka_przebiegu)

    if braki:
        linie.append("Ktoś zgłosił, że czegoś nie dostał:")
        for b in braki[:5]:
            linie.append(
                "  krok " + str(b["krok"]) + ", " + (b["kto"] or "?")
                + ": " + b["cytat"]
            )

    return "\n".join(linie)


def log(tag, message):
    dopisz_do_przebiegu(
        f"[{now()}] [krok {_biezacy_krok}] [{tag}] {message}"
    )
    print(
        f"[{now()}] [{tag}] {message}",
        flush=True
    )


# Ludzkie imiona i kolory ról — żeby narada w terminalu czytała się
# jak rozmowa, a nie jak zrzut logów. Używane tylko przez _speak().
_ROLE_SPEAKERS = {
    "PLANNER": (_IMIONA_ROL["PLANNER"], "cyan", "planowanie"),
    "RESEARCHER": (_IMIONA_ROL["RESEARCHER"], "blue", "research"),
    "ENGINEER": (_IMIONA_ROL["ENGINEER"], "green", "technika"),
    "CRITIC": (_IMIONA_ROL["CRITIC"], "yellow", "ocena"),
    "BROWSER": (_IMIONA_ROL["BROWSER"], "magenta", "tłumaczenie"),
    "WOJTEK": (_IMIONA_ROL["WOJTEK"], "bright_magenta", "pomysły"),
    "MAIN": (_IMIONA_ROL["MAIN"], "bold white", "decyzja"),
    "PROGRESS_ESTIMATOR": (
        _IMIONA_ROL["PROGRESS_ESTIMATOR"], "bright_blue", "postęp"
    ),
    "CODE_REVIEWER": (
        _IMIONA_ROL["CODE_REVIEWER"], "bright_yellow", "analiza kodu"
    ),
    "CODE_FIXER": (
        _IMIONA_ROL["CODE_FIXER"], "bright_green", "poprawka"
    ),
}


def _speak(role, text, preview_chars=400):
    """
    Wypisuje wypowiedź roli. Z `rich` — jako ramkę z imieniem i
    kolorem, czyli czytelną rozmowę. Bez `rich` — dokładnie tak jak
    dotąd, jedną linią logu.

    Na wyraźną prośbę użytkownika: chciał widzieć NORMALNĄ ROZMOWĘ
    zespołu, a nie ciąg jednakowych wpisów "[DEEPSEEK] ROLA: 1341
    znaków | początek: ...". Podgląd jest tu dłuższy niż w starym
    logu (400 zamiast 150 znaków), bo w ramce da się to przeczytać.
    """

    speaker, color, topic = _ROLE_SPEAKERS.get(
        role, (role, "white", "")
    )

    # v278: w terminalu podglad, w pliku CALOSC. To jest sama
    # rozmowa zespolu — jesli czegos nie zapiszemy tutaj, nie da
    # sie potem sprawdzic, kto co komu powiedzial.
    # v390: "ODEBRANE" dopisane ZA rola, nie przed imieniem —
    # znajdz_zgloszone_braki() czyta autora przez
    # linia[4:].split("(")[0], wiec imie musi zostac na swoim
    # miejscu. Slowo idzie tylko tutaj, do pliku przebiegu; ramka
    # na ekranie zostaje taka, jaka byla.
    dopisz_do_przebiegu(
        "\n--- " + speaker + " (" + str(role) + ") — ODEBRANE ---\n"
        + str(text or "").strip() + "\n"
    )

    zapisz_zdarzenie(
        "wypowiedz",
        rola=str(role),
        kto=speaker,
        znaki=len(str(text or ""))
    )

    body = short(str(text or ""), preview_chars).strip()

    if _rich_console is None or _RichPanel is None:
        log(
            "DEEPSEEK",
            f"{role}: "
            + str(len(str(text or "")))
            + " znaków | początek: "
            + short(str(text or ""), 150).replace("\n", " ")
        )
        return

    try:
        title = speaker + (" — " + topic if topic else "")
        _rich_console.print(
            _RichPanel(
                body or "(brak treści)",
                title=title,
                title_align="left",
                border_style=color,
                subtitle=str(len(str(text or ""))) + " znaków",
                subtitle_align="right",
            )
        )
    except Exception:
        # Terminal bez obsługi kolorów/ramek — nigdy nie wolno
        # przez to stracić samej treści.
        log("DEEPSEEK", f"{role}: " + body.replace("\n", " "))


# v390: co POSZLO do agenta — na prosbe uzytkownika.
#
# Dotad cala tresc wyslanej wiadomosci szla wylacznie do pliku
# zdarzen (.jsonl, zdarzenie "prompt", v313), a w przebiegu i na
# ekranie zostawala jedna linia z 70 znakami poczatku:
#
#   [17:17:12] [krok 1] [WYSYŁKA] WOJTEK ← 254 B: zrób agenta...
#
# Wypowiedzi, ktore DOSTAJEMY, sa w przebiegu w calosci i w ramce
# na ekranie — patrz _speak(). Ta funkcja jest jej lustrem w druga
# strone: w pliku cala tresc, na ekranie ramka z podgladem.
_RAMKA_WYSLANE = "=== WYSŁANA WIADOMOŚĆ DO: "
_RAMKA_WYSLANE_KONIEC = "=== KONIEC WYSŁANEJ WIADOMOŚCI ==="


def _wyslano(role, text):
    """
    Co wlasnie poszlo do tej osoby — W CALOSCI, i w pliku, i na
    ekranie.

    v390b: bylo tu preview_chars=400, tak jak przy odbieraniu.
    Uzytkownik poprawil: "co wyslane maja byc pelne od pierwszej
    wiadomosci do roli po cel i kazda jedna wiadomosc cala
    widoczna co wysylamy". Wiec zadnego short() — wysylana
    wiadomosc jest jedyna rzecza w tym programie, ktorej nie
    widzial nigdzie poza plikiem zdarzen.

    Idzie tedy WSZYSTKO, co wychodzi do roli: powitanie z jej
    instrukcjami (pierwsza wiadomosc sesji), zmiana instrukcji,
    fakty o maszynie i kazda wiadomosc kroku razem z celem.
    """

    speaker, color, _topic = _ROLE_SPEAKERS.get(
        role, (role, "white", "")
    )

    tresc = str(text or "")

    dopisz_do_przebiegu(
        "\n" + _RAMKA_WYSLANE + speaker + " (" + str(role) + ") — "
        + _po_ludzku_rozmiar(len(tresc)) + " ===\n"
        + tresc.strip() + "\n"
        + _RAMKA_WYSLANE_KONIEC
    )

    # Bez short(): na ekranie ma byc DOKLADNIE to, co poszlo.
    body = tresc.strip()

    if _rich_console is None or _RichPanel is None:
        # Terminal bez ramek — tresc i tak musi byc cala, wiec
        # idzie surowa, a linia logu zostaje jako naglowek.
        log(
            "WYSYŁKA",
            str(role) + " ← " + _po_ludzku_rozmiar(len(tresc))
        )
        print(body, flush=True)
        return

    try:
        _rich_console.print(
            _RichPanel(
                body or "(pusta wiadomość)",
                title="→ WYSŁANE DO: " + speaker
                + " (" + str(role) + ")",
                title_align="left",
                border_style=color,
                subtitle=_po_ludzku_rozmiar(len(tresc)),
                subtitle_align="right",
            )
        )
    except Exception:
        log(
            "WYSYŁKA",
            str(role) + " ← " + _po_ludzku_rozmiar(len(tresc))
        )
        print(body, flush=True)


# v192 -- zaobserwowany realny, kosztowny bug (log 2026-09-04, cel
# "zrob interakcje glosowa, zadzwon do Beaty"). MAIN kazal zapisac
# skrypt do "~/zadzwon_do_beaty.sh". Ta tresc zadania trafila do
# checklisty przez short(task, 100) -- a 100. znak wypada DOKLADNIE
# w srodku sciezki:
#
#   "...do pliku ~/zad" + "\n...[skrócono]..."
#
# Znacznik obciecia wyladowal w NOWEJ LINII, wiec "~/zad" wygladalo
# jak kompletna, poprawna nazwa pliku. Zespol przeczytal to jako
# fakt: Marek nazwal to wprost "zweryfikowanym dowodem, ze skrypt
# zostal zapisany do ~/zad", MAIN zlecil `cat ~/zad`, Gemini
# zwrocilo "Plik nie istnieje" i caly krok poszedl w kosz.
#
# Ucinanie W SRODKU slowa nie produkuje informacji niepelnej --
# produkuje informacje FALSZYWA, ktora wyglada na kompletna. Tniemy
# wiec na granicy bialego znaku, a gdy jej nie ma w poblizu (jeden
# dlugi token), mowimy wprost, ze ostatnie slowo jest urwane.
_SHORT_BOUNDARY_LOOKBACK = 60


def short(value, limit=1000):

    if value is None:
        return ""

    value = str(value)

    if len(value) <= limit:
        return value

    cut = value[:limit]

    boundary = max(
        cut.rfind(" "),
        cut.rfind("\n"),
        cut.rfind("\t"),
    )

    if boundary >= limit - _SHORT_BOUNDARY_LOOKBACK and boundary > 0:
        # Udalo sie cofnac do granicy slowa -- nic nie jest urwane
        # w polowie, wiec zaden fragment nie udaje calosci.
        return (
            cut[:boundary].rstrip()
            + "\n...[skrócono]..."
        )

    # Jeden bardzo dlugi token (np. base64, dluga sciezka bez spacji)
    # -- nie da sie cofnac sensownie, wiec OSTRZEGAMY WPROST, ze
    # ostatnie slowo jest niepelne. Bez tego czytajacy nie ma jak
    # tego poznac.
    return (
        cut
        + "\n...[skrócono — UWAGA: ostatnie słowo powyżej jest "
        "URWANE W POŁOWIE, nie traktuj go jako pełnej nazwy/"
        "ścieżki]..."
    )


def read_text(path):

    try:
        if not path.exists():
            return ""

        return path.read_text(
            encoding="utf-8",
            errors="ignore"
        )

    except Exception:
        return ""


def write_text(path, value):

    try:
        path.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        path.write_text(
            str(value),
            encoding="utf-8"
        )

        return True

    except Exception as e:
        log("FILE", str(e))
        return False


def read_json(path, default=None):

    try:
        if not path.exists():
            return default

        return json.loads(
            path.read_text(
                encoding="utf-8"
            )
        )

    except Exception:
        return default


def write_json(path, value):

    try:
        path.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        path.write_text(
            json.dumps(
                value,
                ensure_ascii=False,
                indent=2
            ),
            encoding="utf-8"
        )

        return True

    except Exception as e:
        log("FILE", str(e))
        return False


