def _odcisk_tresci(tekst):
    """sha256 tego, co mamy zapisac — nigdy nie rzuca."""

    try:
        return hashlib.sha256(
            str(tekst or "").encode("utf-8", "replace")
        ).hexdigest()

    except Exception:
        return ""


def _odcisk_pliku(p):
    """sha256 tresci pliku albo "" — nigdy nie rzuca."""

    try:
        return hashlib.sha256(Path(p).read_bytes()).hexdigest()
    except Exception:
        return ""


def _sciezka_kanoniczna(p):
    """Jedna postac tej samej sciezki. Nigdy nie rzuca."""

    try:
        return str(Path(str(p)).expanduser().resolve())
    except Exception:
        return str(p)


def _zapisz_autoryzacje_kodu(path, autor="ENGINEER"):
    """
    Trwaly slad: TEN plik, w TEJ tresci, przeszedl kontrole
    autorstwa i zostal polozony przez Pythona.

    Wolane wylacznie tam, gdzie Python realnie zapisuje kod zespolu
    — nigdy "na wszelki wypadek" i nigdy dla pliku, ktory po prostu
    lezy na dysku. Patrz AUTORYZOWANY_KOD_FILE.
    """

    try:
        p = Path(str(path))

        if p.suffix.lower() not in _KOD_SUFIKSY:
            return

        odcisk = _odcisk_pliku(p)

        if not odcisk:
            return

        rejestr = read_json(AUTORYZOWANY_KOD_FILE, {}) or {}

        rejestr[_sciezka_kanoniczna(p)] = {
            "sha256": odcisk,
            "bajtow": p.stat().st_size,
            "autor": str(autor),
            "kiedy": datetime.now().isoformat(timespec="seconds"),
        }

        write_json(AUTORYZOWANY_KOD_FILE, rejestr)

    except Exception:
        pass


def _kod_jest_autoryzowany(path):
    """
    Czy ten plik z kodem ma dowod autoryzacji.

    Dwa zrodla, w tej kolejnosci:
      1. _gdzie_zapisalismy — to uruchomienie, bez czytania dysku.
      2. AUTORYZOWANY_KOD_FILE — poprzednie uruchomienia, ale TYLKO
         gdy tresc pliku nadal zgadza sie z odciskiem zapisanym w
         chwili autoryzacji.

    Samo istnienie pliku, jego polozenie ani rozszerzenie nie
    wystarczaja i wystarczyc nie moga.
    """

    try:
        p = Path(str(path))
    except Exception:
        return False

    if _gdzie_zapisalismy.get(p.name) == str(p):
        return True

    if str(p) in _gdzie_zapisalismy.values():
        return True

    try:
        wpis = (read_json(AUTORYZOWANY_KOD_FILE, {}) or {}).get(
            _sciezka_kanoniczna(p)
        )
    except Exception:
        wpis = None

    if not isinstance(wpis, dict):
        return False

    zapisany = str(wpis.get("sha256") or "")

    return bool(zapisany) and _odcisk_pliku(p) == zapisany


def _zapamietaj_gdzie(path):
    """Nazwa pliku -> gdzie on naprawde lezy. Nigdy nie rzuca."""

    try:
        p = Path(str(path))
        _gdzie_zapisalismy[p.name] = str(p)

        if str(p) not in _przybylo_w_kroku:
            _przybylo_w_kroku.append(str(p))

    except Exception:
        pass


def _co_przybylo_blok():
    """
    Jedna linia: co pojawilo sie na dysku w tym kroku i ile ma.
    Pusty string, gdy nic nie przybylo.
    """

    pozycje = []

    for sciezka in _przybylo_w_kroku:

        try:
            p = Path(sciezka)

            if not p.exists():
                continue

            if p.is_dir():
                pozycje.append(str(p) + "/")
                continue

            pozycje.append(str(p) + " (" + str(p.stat().st_size) + " B)")

        except Exception:
            continue

    if not pozycje:
        return ""

    return "\nNowe na dysku w tym kroku:\n" + "\n".join(
        "- " + x for x in pozycje
    ) + "\n"


def _gdzie_to_jest(tekst):
    """
    Plik, ktorego wlasnie nie znaleziono, a ktory MY zapisalismy
    gdzie indziej. Zwraca (nazwa, prawdziwa sciezka) albo None.
    """

    t = str(tekst or "")

    if "No such file or directory" not in t:
        return None

    for linia in t.splitlines():

        if "No such file or directory" not in linia:
            continue

        for kawalek in re.split(r"[\s:'\"]+", linia):

            szukany = kawalek.rstrip(":")
            nazwa = szukany.split("/")[-1]

            gdzie = _gdzie_zapisalismy.get(nazwa)

            if gdzie and gdzie != szukany:
                return (nazwa, gdzie)

    return None


def _track_project_path(path):
    """
    Zapisuje top-level katalog/plik pod $HOME (albo, dla ścieżek
    wewnątrz $HOME/agent, plik/katalog jeden poziom głębiej — patrz
    _AGENT_DIR_PROTECTED_SECOND_LEVEL_NAMES powyżej), w którym Gemini
    właśnie coś zapisał, do PROJECT_DIRS_FILE — jedyny sposób,
    żeby przy kolejnym NOWYM celu wiedzieć, co właściwie zostało
    wygenerowane w POPRZEDNIEJ sesji (nazwa katalogu projektu jest
    inna za każdym razem, agent jej nie narzuca).

    Woływane z termux_mkdir/termux_write_file/termux_patch_file
    oraz z obsługi write_engineer_code_to w run_agent(). Nigdy nie
    zgłasza wyjątku wyżej — to czysto pomocnicze śledzenie, błąd
    tutaj nie może wywrócić właściwej operacji na pliku.
    """

    try:
        target = Path(str(path)).expanduser().resolve()
        home = Path.home().resolve()

        if home not in target.parents and target != home:
            # Ścieżka spoza $HOME (np. /data/data/com.termux/...
            # poza katalogiem domowym) — nic tu nie śledzimy, to
            # nie jest "projekt użytkownika" w sensie, w jakim tu
            # chodzi.
            return

        relative = target.relative_to(home)

        if not relative.parts:
            return

        top_level_name = relative.parts[0]

        if top_level_name in _PROJECT_TRACKING_EXCLUDED_NAMES:
            return

        if top_level_name.startswith("."):
            return

        if top_level_name == AGENT_DIR.name:

            if len(relative.parts) < 2:
                # Sam katalog "agent" (nie powinno się zdarzyć w
                # praktyce) — nic konkretnego do śledzenia.
                return

            second_level_name = relative.parts[1]

            if (
                second_level_name
                in _AGENT_DIR_PROTECTED_SECOND_LEVEL_NAMES
            ):
                return

            if second_level_name.startswith("."):
                return

            if second_level_name.startswith("agent.py"):
                # Sam skrypt agenta i jego kopie zapasowe
                # (agent.py.bak_YYYYMMDD_HHMMSS z CODE_FIXERA).
                return

            if second_level_name == "web_search.py":
                # Zaobserwowany realny problem (skan $HOME,
                # 2026-08-26): web_search.py leży obok agent.py w
                # AGENT_DIR i jest TWARDĄ zależnością (moduł
                # importowany na starcie: "import web_search") —
                # bez niego program w ogóle się nie uruchomi. Mimo
                # to NIE był chroniony jak agent.py, więc gdyby
                # kiedykolwiek został nadpisany przez
                # write_engineer_code_to/termux_write_file (np.
                # CODE_FIXER "naprawiający" go), trafiłby do
                # PROJECT_DIRS_FILE i mógłby zostać pokazany do
                # usunięcia w zwykłym sprzątaniu — jedno "t" bez
                # wczytania się w listę i program przestałby się
                # uruchamiać.
                return

            top_level_path = str(AGENT_DIR / second_level_name)

        else:

            top_level_path = str(home / top_level_name)

        tracked = read_json(PROJECT_DIRS_FILE, [])

        if not isinstance(tracked, list):
            tracked = []

        if top_level_path not in tracked:
            tracked.append(top_level_path)
            write_json(PROJECT_DIRS_FILE, tracked)

    except Exception:
        pass


def append_memory(path, timestamp, content):
    """
    Dopisuje wpis do pliku pamięci (Markdown).

    Używane m.in. przez review_code() do zapisu analiz
    CODE_REVIEWERA i CODE_FIXERA. Wcześniej ta funkcja była
    wywoływana, ale nigdzie w pliku nie istniała — pierwsze
    realne wywołanie review_code() kończyłoby się NameError
    (po cichu połkniętym przez szerokie except Exception).
    """

    try:
        path.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        entry = (
            "\n\n## "
            + str(timestamp)
            + "\n\n"
            + str(content)
            + "\n"
        )

        with open(path, "a", encoding="utf-8") as f:
            f.write(entry)

        return True

    except Exception as e:
        log("FILE", "append_memory: " + str(e))
        return False


def log_event(event_type, data=None):
    """
    Dopisuje jedno zdarzenie (jeden obiekt JSON na linię) do
    AGENT_DIR/agent_events.jsonl.

    To jest ustrukturyzowany odpowiednik log() — log() jest dla
    człowieka czytającego terminal, log_event() jest dla
    CODE_REVIEWERA i dla ciebie, gdybyś chciał później
    przeanalizować przebieg sesji skryptem zamiast czytać
    dekoracyjne logi tekstowe.
    """

    try:
        entry = {
            "ts": datetime.now().isoformat(),
            "event": event_type,
        }

        entry.update(data or {})

        EVENTS_LOG_FILE.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        with open(EVENTS_LOG_FILE, "a", encoding="utf-8") as f:
            f.write(
                json.dumps(
                    entry,
                    ensure_ascii=False,
                    default=str
                )
                + "\n"
            )

    except Exception:
        # Logowanie nigdy nie może wywrócić właściwej operacji.
        pass


