_PROJECT_FILE_MAX = 12000


def _set_current_project_file(path):
    """Plik, nad ktorym zespol wlasnie pracuje."""

    global _engineer_current_file

    _engineer_current_file = str(path) if path else None


# Skad wiadomo, KTORA linia pliku sie wywalila. Traceback
# Pythona, komunikat basha i awk/sed mowia to wprost — wystarczy
# przeczytac, zamiast pokazywac caly plik i kazac szukac.
_LINIA_BLEDU_RE = re.compile(
    r'File\s+"([^"]+)",\s+line\s+(\d+)'          # Python
    r"|([^\s:]+):\s*line\s+(\d+)"                 # bash
    r"|([^\s:]+):(\d+):\s",                       # sed/awk/gcc
    re.IGNORECASE
)

# Ile linii wokol feralnej pokazujemy.
_OKOLICA_BLEDU = 40


def _linia_bledu_w(sciezka, tekst_bledu):
    """
    Numer linii, na ktorej wywalil sie TEN plik — albo 0.

    Ta sama sztuczka, ktora po stronie agent.py robi od dawna
    extract_function_source(): zamiast podawac 12000 znakow i
    liczyc, ze ktos znajdzie w nich wlasciwe miejsce, wycinamy
    dokladnie to miejsce, o ktorym mowi blad.
    """

    tekst = str(tekst_bledu or "")

    if not tekst.strip():
        return 0

    nazwa = str(sciezka).split("/")[-1]

    for m in _LINIA_BLEDU_RE.finditer(tekst):

        for plik_g, linia_g in ((1, 2), (3, 4), (5, 6)):

            plik = m.group(plik_g)

            if not plik:
                continue

            if plik.split("/")[-1] != nazwa:
                continue

            try:
                return int(m.group(linia_g))
            except (TypeError, ValueError):
                return 0

    return 0


def _okolica_linii(tresc, linia):
    """Kawalek pliku wokol wskazanej linii, z numeracja."""

    linie = tresc.split("\n")

    od = max(0, linia - 1 - _OKOLICA_BLEDU // 2)
    do = min(len(linie), od + _OKOLICA_BLEDU)

    szerokosc = len(str(do))

    return "\n".join(
        str(nr + 1).rjust(szerokosc) + " | " + linie[nr]
        for nr in range(od, do)
    ), od + 1, do


def _plik_w_grze(*teksty):
    """
    Czy plik, nad ktorym pracujemy, pada w tym, co sie wlasnie
    dzieje — w planie albo w bledzie.
    """

    if not _engineer_current_file:
        return False

    nazwa = str(_engineer_current_file).split("/")[-1].strip()

    if not nazwa:
        return False

    return any(nazwa in str(t or "") for t in teksty)


def _current_project_file_block(tekst_bledu=""):
    """
    Aktualna tresc pliku, odczytana Z DYSKU TERAZ.

    Gdy z bledu da sie wyczytac numer linii — pokazujemy okolice tej
    linii, z numeracja, zamiast calego pliku. Naprawiajacy dostaje
    wtedy dokladnie to miejsce, ktore ma poprawic, a nie poczatek i
    koniec pliku z dziura w srodku.

    Zwraca "" gdy nie ma nad czym pracowac albo pliku nie da sie
    odczytac — nigdy nie zgadujemy, co w nim jest.
    """

    if not _engineer_current_file:
        return ""

    try:
        p = _resolve_home_relative_path(_engineer_current_file)

        if not p.exists():
            return (
                "\n\nAKTUALNY STAN PLIKU " + str(p) + ": PLIKU NIE MA "
                "na dysku (sprawdzone teraz). Jeśli miał tam być — "
                "trzeba go utworzyć od zera, nie poprawiać.\n"
            )

        tresc = p.read_text(encoding="utf-8", errors="replace")

    except Exception:
        return ""

    naglowek = (
        "\n\nTAK WYGLĄDA TEN PLIK TERAZ — " + str(p) + " ("
        + str(len(tresc)) + " B, odczytane z dysku w tej chwili, nie "
        "z czyjejś pamięci):\n"
    )

    stopka = (
        "\n[To jest STAN FAKTYCZNY pliku. Jeśli poprawiasz go przez "
        "SZUKAJ/ZAMIEŃ — skopiuj fragment DOKŁADNIE stąd, znak w "
        "znak, razem z wcięciami. Fragment musi występować w pliku "
        "dokładnie raz, inaczej poprawka zostanie odrzucona.]\n"
    )

    linia = _linia_bledu_w(p, tekst_bledu)

    if linia and 0 < linia <= tresc.count("\n") + 1:

        okolica, od, do = _okolica_linii(tresc, linia)

        return (
            "\n\nTAK WYGLĄDA " + str(p) + " W MIEJSCU, KTÓRE SIĘ "
            "WYWALIŁO — linia " + str(linia) + ", pokazuję "
            + str(od) + "-" + str(do) + " z " + str(
                tresc.count("\n") + 1
            ) + " (odczytane z dysku w tej chwili):\n"
            + okolica
            + "\n\n[Numery linii są tylko dla orientacji — nie ma "
            "ich w pliku. Resztę pliku możesz odczytać przez "
            "termux_read_file.]"
            + stopka
        )

    if len(tresc) <= _PROJECT_FILE_MAX:
        return naglowek + tresc + stopka

    polowa = _PROJECT_FILE_MAX // 2

    return (
        naglowek
        + tresc[:polowa]
        + "\n\n[...POMINIĘTO ŚRODEK PLIKU ("
        + str(len(tresc) - _PROJECT_FILE_MAX)
        + " B) — jest za duży, żeby pokazać go w całości. Poniżej "
        "koniec pliku. Jeśli poprawiasz fragment ze środka, poproś "
        "najpierw o odczytanie tej konkretnej części...]\n\n"
        + tresc[-polowa:]
        + stopka
    )



def _remember_engineer_code_result(path, result):
    """
    Zapamietuje, jak zachowal sie kod Bartka, zeby oddac mu to wprost.
    Nigdy nie rzuca wyzej — to informacja, nie warunek dzialania.
    """

    global _engineer_code_feedback

    try:
        if not isinstance(result, dict):
            return

        tool_result = result.get("tool_result")

        if not isinstance(tool_result, dict):
            # Przy sukcesie tool_result jest pusty (patrz
            # _run_script_directly) — surowy wynik lezy obok.
            tool_result = result.get("shell_result")

        if not isinstance(tool_result, dict):
            tool_result = {}

        _engineer_code_feedback = {
            "path": str(path),
            "ok": bool(result.get("ok")),
            "returncode": tool_result.get("returncode"),
            "stdout": str(tool_result.get("stdout") or ""),
            "stderr": str(tool_result.get("stderr") or ""),
            "report": str(result.get("report") or ""),
        }

    except Exception:
        _engineer_code_feedback = None


def _engineer_feedback_block():
    """
    Blok oddawany Bartkowi: co realnie zrobil jego kod. Opróżnia sam
    siebie — mowimy o tym raz, przy najblizszej okazji.
    """

    global _engineer_code_feedback

    dane = _engineer_code_feedback
    _engineer_code_feedback = None

    if not dane:
        return ""

    naglowek = (
        "\n\nURUCHOMILISMY TWOJ KOD (" + dane["path"] + ") — oto co "
        "z niego wyszlo NAPRAWDE"
    )

    if dane["ok"]:
        naglowek += " (zakonczyl sie bez bledu):"
    else:
        naglowek += (
            " (NIE POWIODL SIE, kod wyjscia "
            + str(dane.get("returncode")) + "):"
        )

    czesci = [naglowek]

    if dane["stdout"].strip():
        czesci.append("\nWYJSCIE:\n" + short(dane["stdout"], 2500))

    if dane["stderr"].strip():
        czesci.append("\nBLEDY:\n" + short(dane["stderr"], 2000))

    # v383: gdy program nic nie wypisal, w to miejsce szla PROZA z
    # wykonania — a zdanie ponizej mowilo o niej "to jest surowy
    # wynik z urzadzenia, nie czyjes streszczenie". To bylo
    # nieprawda dokladnie wtedy, gdy mialo najwieksze znaczenie:
    # Bartek dostawal czyjs opis i byl zapewniany, ze to pomiar.
    # Mowimy wiec, czym ta tresc jest naprawde.
    _bylo_wyjscie = bool(
        dane["stdout"].strip() or dane["stderr"].strip()
    )

    if not _bylo_wyjscie:
        czesci.append(
            "\nProgram nie wypisal ANI JEDNEGO znaku — ani na "
            "wyjscie, ani na bledy. Ponizej jest RELACJA z "
            "wykonania, czyli opis slowami, a nie to, co wypisalo "
            "urzadzenie:\n"
            + short(dane["report"], 1500)
        )

    czesci.append(
        (
            "\nTo jest surowy wynik z urzadzenia, nie czyjes "
            "streszczenie. "
            if _bylo_wyjscie else
            "\nSurowego wyjscia nie bylo, wiec powyzsze to opis, a "
            "nie pomiar. "
        )
        + "Jesli cos nie zadzialalo — popraw to, ale podaj TYLKO "
        "zmieniony fragment przez SZUKAJ/ZAMIEN albo caly plik, gdy "
        "poprawka jest wieksza niz polowa. Nie przepisuj calosci bez "
        "potrzeby."
    )

    return "".join(czesci)


