ANDROID_ACTION_TIMEOUT = int(
    os.environ.get("ANDROID_ACTION_TIMEOUT", "20")
)


def _android_with_deadline(label, fn, timeout=None):
    """
    Wykonuje blokujace wywolanie uiautomator2 z twardym limitem
    czasu. Po przekroczeniu zwraca blad zamiast wisiec.

    Watek zostaje porzucony (nie da sie bezpiecznie zabic watku w
    Pythonie), ale agent idzie dalej — to jedyna roznica miedzy
    "krok sie nie udal" a "program stoi dziesiec minut".
    """

    limit = int(timeout or ANDROID_ACTION_TIMEOUT)
    wynik = {}

    def _praca():
        try:
            wynik["value"] = fn()
        except Exception as e:
            wynik["error"] = e

    watek = _threading.Thread(target=_praca, daemon=True)
    watek.start()
    watek.join(limit)

    if watek.is_alive():

        log(
            "ANDROID",
            label + ": brak odpowiedzi po " + str(limit) + " s — "
            "przerywam. Ekran systemowy (np. trwajace polaczenie) "
            "potrafi zablokowac uiautomator2."
        )

        raise TimeoutError(
            label + ": urzadzenie nie odpowiedzialo w " + str(limit)
            + " s. To NIE znaczy, ze gest jest zly — znaczy, ze "
            "uiautomator2 nie ma teraz dostepu do ekranu (tak "
            "dziala Android przy aktywnym polaczeniu albo ekranie "
            "systemowym). Sprobuj czegos, co nie wymaga rysowania "
            "po ekranie."
        )

    if "error" in wynik:
        raise wynik["error"]

    return wynik.get("value")


def android_swipe(
    x1,
    y1,
    x2,
    y2,
    duration=0.3
):
    """
    Wykonuje swipe po współrzędnych — potrzebne dla gier/UI
    sterowanych gestem, list do przewinięcia itp.
    """

    global android_device

    if android_device is None:
        if not init_android():
            return {
                "ok": False,
                "error": "Android niedostępny."
            }

    try:
        _android_with_deadline(
            "android_swipe",
            lambda: android_device.swipe(
                int(x1),
                int(y1),
                int(x2),
                int(y2),
                duration=float(duration)
            )
        )

        return {
            "ok": True,
            "action": "swipe",
            "from": [int(x1), int(y1)],
            "to": [int(x2), int(y2)]
        }

    except Exception as e:
        return {
            "ok": False,
            "action": "swipe",
            "error": str(e)
        }


# Ścieżki wszystkich zrzutów ekranu zrobionych w TYM uruchomieniu
# (android_screenshot/android_screenshot_ocr, niezależnie od tego,
# gdzie Gemini je zapisał) — użytkownik dał jawną, trwałą zgodę na
# ich automatyczne kasowanie bez pytania o potwierdzenie, więc są
# śledzone tu osobno od _track_project_path() (ta lista dalej
# wymaga confirmu dla reszty wygenerowanych plików projektu).
# Patrz _cleanup_screenshots_silently().
_screenshot_paths_this_run = []


def _cleanup_screenshots_silently():
    """
    Kasuje WSZYSTKIE zrzuty ekranu — te z TEGO uruchomienia
    (_screenshot_paths_this_run, niezależnie od tego, gdzie Gemini
    je zapisał) oraz wszystko, co zalega w domyślnym katalogu
    AGENT_DIR/screenshots/ (np. resztki po poprzednim, twardo
    zabitym procesie) — BEZ pytania o potwierdzenie. Użytkownik dał
    na to jawną, trwałą zgodę: zrzuty to jednorazowy, nieczytany
    przez nikogo dowód wykonania, nie coś, co warto zachowywać albo
    o co warto pytać za każdym razem jak resztę wygenerowanych
    plików projektu.

    Wołane i na starcie programu (sprząta resztki sprzed ewentualnej
    awarii poprzedniego uruchomienia), i przez atexit (normalne
    zamknięcie, także Ctrl+C).
    """

    removed = 0

    for raw_path in list(_screenshot_paths_this_run):
        try:
            Path(raw_path).unlink(missing_ok=True)
            removed += 1
        except Exception:
            pass

    _screenshot_paths_this_run.clear()

    try:
        screenshots_dir = AGENT_DIR / "screenshots"

        if screenshots_dir.is_dir():
            for p in screenshots_dir.glob("*.png"):
                try:
                    p.unlink()
                    removed += 1
                except Exception:
                    pass
    except Exception:
        pass

    # Resztki sprzed wprowadzenia tego mechanizmu (v50) albo z
    # procesów zabitych PRZED zarejestrowaniem ścieżki w
    # _screenshot_paths_this_run — Gemini konsekwentnie nazywa
    # zrzuty z prefiksem "screenshot" (zgodnie z przykładami w
    # promptach), np. screenshot_krok3.png, screenshot_wikipedia.png,
    # screenshot_ustawienia.png. Sprzątamy je też, TYLKO na
    # najwyższym poziomie $HOME (nie rekurencyjnie — nie ruszamy
    # katalogów projektu).
    try:
        for p in HOME.glob("screenshot*.png"):
            try:
                p.unlink()
                removed += 1
            except Exception:
                pass
    except Exception:
        pass

    if removed:
        log(
            "MAIN",
            "Usunięto " + str(removed) + " zrzutów ekranu "
            "(automatycznie, bez pytania — stała zgoda użytkownika)."
        )


# Urzadzenia, ktore proces potrafi TRZYMAC zajete po sobie, i
# komenda, ktora je zwalnia. Pary sa faktem o Termuksie, nie o
# jakimkolwiek celu — dopisanie kolejnej pozycji nie wymaga wiedzy o
# tym, co akurat robi zespol.
_URZADZENIA_DO_ZWOLNIENIA = (
    ("termux-microphone-record", ["termux-microphone-record", "-q"]),
)


def _zwolnij_zajete_urzadzenia():
    """
    Zwalnia urzadzenie, ktore NAPRAWDE jest w tej chwili zajete.

    v306: sprawdzamy, zanim zwolnimy.

    W v305 wolalem `termux-microphone-record -q` przy KAZDYM wyjsciu
    z programu. Uzytkownik przypomnial zasade, ktora obowiazuje tu od
    poczatku: program jest UNIWERSALNY. Cel bywa asystentem glosowym,
    ale rownie dobrze bywa czymkolwiek innym — i wtedy wolanie
    komendy od mikrofonu jest zalozeniem o celu, a nie reakcja na
    fakt.

    Wiec najpierw patrzymy, czy taki proces w ogole chodzi. Chodzi —
    zwalniamy. Nie chodzi — nie ma czego zwalniac i nie robimy nic.
    Przy celu bez dzwieku ten kod nie wykona ani jednej komendy.

    Nigdy nie rzuca — to sprzatanie przy wyjsciu.
    """

    for nazwa, komenda in _URZADZENIA_DO_ZWOLNIENIA:

        try:
            czy_chodzi = subprocess.run(
                ["pgrep", "-f", nazwa],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=10,
            ).returncode == 0

        except Exception:
            continue

        if not czy_chodzi:
            continue

        print("Zwalniam " + nazwa + " — zostalo zajete.")

        try:
            subprocess.run(
                komenda,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=10,
            )
        except Exception:
            pass


def _zatrzymaj_to_co_zostawilismy():
    """
    Przy wyjsciu gasimy to, co sami puscilismy w tle — i zwalniamy
    mikrofon.

    ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-11 15:23).
    ~/asystent.sh nagrywal w petli. Uzytkownik przerwal agenta
    Ctrl+C, agent zwolnil wake-lock i wyszedl — a skrypt nagrywal
    dalej. Uzytkownik pisal: "program mi sie zaciol i go
    zatrzymalem, ale mikrofon sie wlacza i wylacza". Musial szukac
    komendy, zeby ubic cos, co my uruchomilismy.

    Skoro agent konczy prace, nikt juz nie przeczyta logow tych
    procesow ani nie odbierze ich wynikow. Zostawianie ich przy
    zyciu nie sluzy nikomu.

    Osobno zwalniamy urzadzenia, ktore zostaly zajete — ale tylko te,
    ktore NAPRAWDE sa zajete. Patrz _zwolnij_zajete_urzadzenia().

    Nigdy nie rzuca — to sprzatanie przy wyjsciu, nie robota.
    """

    for pid, proces in list(_procesy_w_tle.items()):

        try:
            if proces.poll() is not None:
                continue

            print(
                "Zatrzymuje to, co uruchomilem w tle (pid "
                + str(pid) + ")."
            )

            try:
                _grupa = os.getpgid(pid)

                # Zabezpieczenie: NIGDY nie ubijamy wlasnej grupy.
                # Procesy w tle dostaja swoja (start_new_session),
                # ale gdyby to sie kiedys zmienilo, killpg zabilby
                # terminal uzytkownika razem z agentem.
                if _grupa and _grupa != os.getpgrp():
                    os.killpg(_grupa, signal.SIGTERM)
                else:
                    proces.terminate()

            except Exception:
                proces.terminate()

            try:
                proces.wait(timeout=5)
            except Exception:
                try:
                    proces.kill()
                except Exception:
                    pass

        except Exception:
            continue

    _zwolnij_zajete_urzadzenia()


atexit.register(_zatrzymaj_to_co_zostawilismy)


atexit.register(_cleanup_screenshots_silently)


def android_screenshot(path=None):
    """
    Prawdziwy zrzut ekranu (PNG), nie tylko tekstowy dump drzewa
    UI. Potrzebne do fizycznej weryfikacji na końcu (np. "czy gra
    faktycznie się uruchomiła i coś rysuje na ekranie" to co innego
    niż "czy proces istnieje").

    Wcześniej android_screen() było tylko aliasem do
    android_summary() (tekst), więc nic realnie nie fotografowało
    ekranu.
    """

    global android_device

    if android_device is None:
        if not init_android():
            return {
                "ok": False,
                "error": "Android niedostępny."
            }

    try:
        # v190: ta sama zasada co v188 — goła względna nazwa podana
        # przez Gemini ("zrzut.png") musi wylądować w $HOME, tam
        # gdzie potem szuka jej termux_read_file/termux_ls, a NIE w
        # katalogu, z którego wystartował proces agent.py.
        target = _resolve_home_relative_path(
            str(path)
            if path
            else str(AGENT_DIR / "screenshots" /
                (datetime.now().strftime("%Y%m%d_%H%M%S") + ".png"))
        )

        target.parent.mkdir(
            parents=True,
            exist_ok=True
        )

        android_device.screenshot(
            str(target)
        )

        # Nikt (Gemini/DeepSeek) nie odczytuje TREŚCI tego pliku —
        # użytkownik dał jawną, trwałą zgodę na automatyczne
        # kasowanie zrzutów bez pytania o potwierdzenie za każdym
        # razem (w przeciwieństwie do reszty wygenerowanych plików
        # projektu). Śledzimy więc ścieżkę tu, żeby
        # _cleanup_screenshots_silently() (atexit + start programu)
        # mogła ją posprzątać automatycznie, bez confirmu.
        _screenshot_paths_this_run.append(str(target))

        return {
            "ok": target.exists(),
            "action": "screenshot",
            "path": str(target),
            "size_bytes": (
                target.stat().st_size
                if target.exists() else 0
            )
        }

    except Exception as e:
        return {
            "ok": False,
            "action": "screenshot",
            "error": str(e)
        }


def android_screenshot_ocr(path=None, lang=None):
    """
    Zrzut ekranu + NATYCHMIASTOWE rozpoznanie tekstu lokalnie przez
    Tesseract OCR (pkg install tesseract w Termuksie — UWAGA: pakiet
    nazywa się dokładnie "tesseract", NIE "tesseract-ocr") — ZERO
    wywołań do Gemini/innego modelu, zero kosztu limitu API,
    działa całkowicie offline na urządzeniu. Zwraca sam TEKST
    widoczny na ekranie (nie plik obrazu) — przydatne tam, gdzie
    android_state (tekstowy dump drzewa UI/accessibility) nie
    pokazuje treści, np. tekst wyrenderowany wewnątrz WebView/
    Canvas/gry, który nie ma odpowiadającego węzła accessibility.

    NIE pomoże przy weryfikacji czystej grafiki bez tekstu (kształty,
    kolory, układ elementów) — do tego nadal potrzebny jest ręczny
    podgląd zrzutu przez człowieka, nie automatyczna analiza.
    """

    screenshot_result = android_screenshot(path)

    if not screenshot_result.get("ok"):
        return screenshot_result

    target = screenshot_result["path"]

    tesseract_bin = shutil.which("tesseract")

    if not tesseract_bin:
        return {
            "ok": False,
            "error": (
                "Brak zainstalowanego 'tesseract' w Termuksie. "
                "POPRAWNA nazwa pakietu to dokładnie 'tesseract' "
                "(NIE 'tesseract-ocr' — takiego pakietu nie ma w "
                "repozytorium Termux, próba jego instalacji zawsze "
                "kończy się 'Unable to locate package'). Zainstaluj: "
                "pkg install tesseract — angielski działa od razu, "
                "bez dodatkowego pakietu językowego. Dla innych "
                "języków (np. polskiego) NIE MA osobnego pakietu do "
                "zainstalowania — trzeba ręcznie pobrać plik danych "
                "językowych, np.: curl -o "
                "$PREFIX/share/tessdata/pol.traineddata "
                "https://raw.githubusercontent.com/tesseract-ocr/"
                "tessdata/4.0.0/pol.traineddata"
            ),
            "path": target
        }

    try:
        cmd = [tesseract_bin, target, "-"]

        if lang:
            cmd += ["-l", str(lang)]

        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=30
        )

        if result.returncode != 0:

            stderr_text = str(result.stderr or "")

            # Zaobserwowany realny przypadek (2026-08-30): to samo
            # polecenie z lang="pol" zawiodło TU, nie w gałęzi "brak
            # tesseract_bin" wyżej — sam tesseract JEST zainstalowany
            # i uruchomił się, ale zabrakło pliku danych językowych
            # (pol.traineddata). Poprzednio ta gałąź zwracała goły,
            # surowy stderr tesseracta ("Failed loading language
            # 'pol'") bez ŻADNEJ wskazówki, jak to naprawić — mimo że
            # dokładnie taka wskazówka (curl .../pol.traineddata) już
            # istniała w kodzie, tylko w NIEWŁAŚCIWEJ gałęzi (tej dla
            # brakującego binarium tesseract, nie brakującego pakietu
            # językowego). Wykrywamy ten konkretny przypadek po treści
            # stderr i dołączamy tę samą, działającą wskazówkę —
            # uogólnioną na FAKTYCZNIE żądany język, nie tylko polski.
            if (
                "failed loading language" in stderr_text.lower()
                or "error opening data file" in stderr_text.lower()
            ):

                missing_lang = str(lang or "pol")

                return {
                    "ok": False,
                    "error": (
                        "Brak pliku danych językowych dla tesseract "
                        "(lang=\"" + missing_lang + "\") — sam "
                        "tesseract JEST zainstalowany, ale brakuje "
                        "pakietu językowego. Dla większości języków "
                        "(w tym polskiego) NIE MA osobnego pakietu w "
                        "repozytorium Termux — pobierz plik ręcznie: "
                        "curl -o $PREFIX/share/tessdata/"
                        + missing_lang + ".traineddata "
                        "https://raw.githubusercontent.com/"
                        "tesseract-ocr/tessdata/4.0.0/"
                        + missing_lang + ".traineddata — "
                        "albo, jeśli treść na ekranie jest po "
                        "angielsku/cyframi, wywołaj ponownie BEZ "
                        "parametru lang (domyślny angielski działa "
                        "od razu, bez dodatkowego pobierania). "
                        "Surowy błąd tesseracta: "
                        + short(stderr_text, 300)
                    ),
                    "path": target
                }

            return {
                "ok": False,
                "error": (
                    "tesseract zakończył się błędem: "
                    + short(stderr_text, 500)
                ),
                "path": target
            }

        return {
            "ok": True,
            "action": "screenshot_ocr",
            "path": target,
            "text": result.stdout.strip()
        }

    except Exception as e:
        return {
            "ok": False,
            "error": str(e),
            "path": target
        }


# Pakiety już pomyślnie uruchomione w BIEŻĄCYM celu (patrz
# android_launch_app niżej) — zaobserwowany realny problem: zespół
# potrafił kilkukrotnie kazać Gemini otworzyć i "potwierdzić" TĘ SAMĄ
# aplikację (np. Zegar) w różnych krokach tego samego celu, bo za
# każdym razem TASK był sformułowany innymi słowami, więc dokładne
# dopasowanie tekstu w _checklist_duplicate_message() tego nie
# łapało. Śledzimy więc powtórki po nazwie PAKIETU — jedynym
# stabilnym, ustrukturyzowanym identyfikatorze, jaki tu w ogóle mamy
# (argument narzędzia, nie wolny tekst TASK-u) — i dajemy o tym znać
# jako miękkie ostrzeżenie (nie blokadę: czasem faktyczna ponowna
# próba jest uzasadniona, np. po awarii). Czyszczone razem z resztą
# stanu celu w maybe_restart_team_sessions_for_new_goal().
_confirmed_app_launches = {}


def android_launch_app(package):
    """
    Uruchamia zainstalowaną aplikację po nazwie pakietu przez
    `adb shell monkey` — w odróżnieniu od `am start -n pakiet/
    .Activity` nie wymaga znajomości nazwy głównej activity, więc
    działa dla DOWOLNEJ aplikacji na urządzeniu (nie tylko tej
    budowanej w bieżącym projekcie).

    To jest brakujący kawałek "rąk": android_screenshot/
    android_click/android_state już działają na CAŁYM ekranie
    systemu (nie tylko w oknie Termuksa), ale wcześniej nie było
    jawnego narzędzia, żeby SAMEMU otworzyć inną aplikację — np.
    zbudowaną i zainstalowaną (`adb install`) grę, zanim zrobi się
    zrzut ekranu jako dowód, że coś faktycznie się renderuje.
    """

    package = str(package or "").strip()

    if not package:
        return {
            "ok": False,
            "error": "Pusta nazwa pakietu."
        }

    result = execute_shell(
        "adb shell monkey -p " + shlex.quote(package)
        + " -c android.intent.category.LAUNCHER 1",
        timeout=20
    )

    started = bool(
        result.get("ok")
        and "Events injected: 1" in result.get("stdout", "")
    )

    already_launched_note = ""

    if started:

        prior = _confirmed_app_launches.get(package)

        if prior:
            already_launched_note = (
                "Ta aplikacja (" + package + ") była już pomyślnie "
                "otwarta i potwierdzona wcześniej W TYM SAMYM CELU "
                "(pierwszy raz: " + prior + ") — czyli ten krok jest "
                "już za nami i otwarcie jej drugi raz zajmie cały "
                "cykl TASK-u na coś zrobionego. Ma to sens tylko "
                "wtedy, gdy tamta sesja faktycznie padła. UWAGA: "
                "jeśli byłeś W TRAKCIE "
                "interakcji z tą aplikacją (np. wpisane, ale jeszcze "
                "niezatwierdzone dane), ponowne uruchomienie MOŻE "
                "zresetować jej stan do początkowego — zaobserwowany "
                "realny przypadek: wpisane cyfry w kalkulatorze "
                "zniknęły (wrócił do '0') po ponownym "
                "android_launch_app tego samego pakietu. Jeśli "
                "podejrzewasz, że apka jest po prostu w tle (nie "
                "zamknięta), sprawdź najpierw android_state zamiast "
                "od razu relaunchować."
            )

        _confirmed_app_launches[package] = datetime.now().isoformat()

    output = {
        "ok": started,
        "action": "launch_app",
        "package": package,
        "detail": short(
            result.get("stdout", "")
            + result.get("stderr", ""),
            500
        )
    }

    if already_launched_note:
        output["already_launched_note"] = already_launched_note

    return output


def android_list_packages(filter_text=None):
    """
    Lista zainstalowanych pakietów PRZEZ ADB — omija ograniczenie
    "package visibility" (Android 11+), przez które gołe `pm list
    packages` uruchomione w SAMYM Termuksie (zwykła aplikacja) widzi
    tylko ograniczony podzbiór innych zainstalowanych aplikacji, nie
    wszystkie.

    Zaobserwowany realny, powtarzający się problem: Gemini
    wielokrotnie pisał WŁASNY skrypt bash z gołym `pm list packages
    | grep ...` (czasem pamiętając o dodaniu `adb shell`, czasem
    zapominając — niezawodność promptu okazała się niewystarczająca,
    jak przy innych podobnych przypadkach w tym projekcie), który
    konsekwentnie nie znajdował aplikacji FAKTYCZNIE zainstalowanych
    na urządzeniu (Kalkulator, Zegar) — zamiast czekać, aż model
    zawsze pamięta o `adb shell`, to narzędzie robi to sam, za każdym
    razem, strukturalnie.
    """

    command = "adb shell pm list packages"

    if filter_text:
        command += " | grep -i " + shlex.quote(str(filter_text))

    result = execute_shell(command, timeout=20)

    # v324: grep, ktory nic nie znalazl, konczy sie jedynka. To nie
    # jest awaria narzedzia — to odpowiedz "nie ma".
    #
    # ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-12 21:43, krok 2).
    # Zespol sprawdzal, czy Linphone sie juz zainstalowal:
    #
    #   {"ok": false, "returncode": 1, "stdout": "", "stderr": "",
    #    "command": "adb shell pm list packages | grep -i linphone"}
    #
    # Przeczytali to jako BLAD NARZEDZIA i przez dwa nastepne kroki
    # szukali obejscia (android_run_in_new_window, pm path, pelne
    # sciezki), zamiast po prostu poczekac. Uzytkownik: "pobieranie
    # troche trwa (...) oni widza blad".
    #
    # Wiec mowimy prawde: nic nie pasuje. I skoro i tak pytamy, czy
    # cos JUZ jest na telefonie, patrzymy jeszcze raz po chwili —
    # dokladnie tak, jak robi czlowiek, ktory wlasnie klikna
    # "Zainstaluj".
    _nic_nie_pasuje = (
        filter_text
        and result.get("returncode") == 1
        and not str(result.get("stdout") or "").strip()
        and not str(result.get("stderr") or "").strip()
    )

    if _nic_nie_pasuje:

        log(
            "ANDROID",
            "Nie ma jeszcze nic pasujacego do '" + str(filter_text)
            + "'. Patrze drugi raz za "
            + str(DRUGIE_SPOJRZENIE) + " s — instalacja albo "
            "pobieranie moga wlasnie trwac."
        )

        time.sleep(DRUGIE_SPOJRZENIE)

        drugie = execute_shell(command, timeout=20)

        _dalej_nic = (
            drugie.get("returncode") == 1
            and not str(drugie.get("stdout") or "").strip()
            and not str(drugie.get("stderr") or "").strip()
        )

        if _dalej_nic:

            return {
                "ok": True,
                "packages": [],
                "count": 0,
                "filter": str(filter_text),
                "sprawdzone_dwa_razy": True,
                "message": (
                    "Nie ma tego na telefonie. Sprawdziłem dwa razy, "
                    "w odstępie " + str(DRUGIE_SPOJRZENIE)
                    + " s — na wypadek, gdyby pobieranie albo "
                    "instalacja właśnie trwały. Dalej pusto."
                )
            }

        log(
            "ANDROID",
            "Za pierwszym razem nie bylo, po "
            + str(DRUGIE_SPOJRZENIE) + " s juz jest — instalacja "
            "wlasnie sie konczyla."
        )

        result = drugie
        result["sprawdzone_dwa_razy"] = True

    if not result.get("ok"):
        return result

    packages = []

    for line in result.get("stdout", "").splitlines():

        line = line.strip()

        if line.startswith("package:"):
            packages.append(line[len("package:"):])

    _wynik = {
        "ok": True,
        "packages": packages,
        "count": len(packages)
    }

    if result.get("sprawdzone_dwa_razy"):
        _wynik["sprawdzone_dwa_razy"] = True
        _wynik["message"] = (
            "Za pierwszym razem tego nie było — po "
            + str(DRUGIE_SPOJRZENIE) + " s już jest. Instalacja "
            "właśnie się kończyła."
        )

    return _wynik


def _ensure_termux_allow_external_apps():
    """
    RUN_COMMAND (uruchomienie komendy w NOWYM, widocznym oknie/
    sesji Termuksa) wymaga allow-external-apps=true w
    ~/.termux/termux.properties. Domyślnie to WYŁĄCZONE.

    Dopisuje brakującą linię, jeśli jej nie ma — ale Termux czyta
    ten plik TYLKO przy starcie aplikacji (albo po ręcznym "Reload
    Settings" z powiadomienia Termuksa), więc jeśli dopiero co
    dopisaliśmy tę linię, RUN_COMMAND i tak nie zadziała, dopóki
    ktoś nie zrestartuje Termuksa / nie kliknie Reload Settings.

    Zwraca True, jeśli linia JUŻ była obecna wcześniej (można
    próbować od razu), False jeśli właśnie ją dopisano.
    """

    props_path = Path(
        "~/.termux/termux.properties"
    ).expanduser()

    content = read_text(props_path)

    if re.search(
        r"^\s*allow-external-apps\s*=\s*true\s*$",
        content,
        re.MULTILINE
    ):
        return True

    props_path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    new_content = (
        content.rstrip("\n")
        + ("\n" if content.strip() else "")
        + "allow-external-apps=true\n"
    )

    write_text(props_path, new_content)

    log(
        "TERMUX",
        "Dopisano allow-external-apps=true do "
        + str(props_path)
        + " — RUN_COMMAND zadziała dopiero po restarcie Termuksa "
        "albo 'Reload Settings' z powiadomienia Termuksa."
    )

    return False


def android_run_in_new_window(command, background=False):
    """
    Uruchamia komendę w NOWYM, widocznym oknie/sesji Termuksa
    przez wbudowany w Termux mechanizm RUN_COMMAND — w odróżnieniu
    od termux_run_background (ten sam proces, log tylko w pliku),
    to faktycznie OTWIERA nowe okno Termuksa z tą komendą, więc
    output jest widoczny na żywo, osobno od głównej sesji agenta.

    Wymaga allow-external-apps=true w termux.properties — jeśli
    dopiero teraz zostało włączone, ta i kolejne próby mogą się
    nie udać, dopóki Termux nie zostanie zrestartowany (patrz pole
    "needs_termux_restart" w wyniku).
    """

    command = str(command or "").strip()

    if not command:
        return {
            "ok": False,
            "error": "Pusta komenda."
        }

    already_enabled = _ensure_termux_allow_external_apps()

    script_dir = Path(
        "~/.termux_run_command_scripts"
    ).expanduser()

    script_dir.mkdir(
        parents=True,
        exist_ok=True
    )

    script_path = script_dir / (uuid.uuid4().hex + ".sh")

    script_path.write_text(
        "#!/data/data/com.termux/files/usr/bin/sh\n"
        + command
        + "\n",
        encoding="utf-8"
    )

    try:
        script_path.chmod(0o700)
    except Exception:
        pass

    background_flag = "true" if background else "false"

    result = execute_shell(
        "adb shell am start -n "
        "com.termux/com.termux.app.RunCommandActivity "
        "-a com.termux.RUN_COMMAND "
        "--es com.termux.RUN_COMMAND_PATH '"
        + str(script_path)
        + "' --ez com.termux.RUN_COMMAND_BACKGROUND "
        + background_flag,
        timeout=15
    )

    output = (
        result.get("stdout", "")
        + result.get("stderr", "")
    )

    denied = (
        "SecurityException" in output
        or "Permission Denial" in output
    )

    started = bool(
        result.get("ok")
        and "Starting: Intent" in output
        and not denied
    )

    detail = short(output, 500)

    if not already_enabled:
        detail = (
            "UWAGA: allow-external-apps właśnie zostało włączone "
            "w termux.properties — RUN_COMMAND zadziała dopiero "
            "po restarcie Termuksa albo 'Reload Settings' z "
            "powiadomienia Termuksa. "
        ) + detail

    if denied:
        detail = (
            "ODRZUCONE przez system — allow-external-apps "
            "prawdopodobnie nadal wyłączone (Termux nie został "
            "zrestartowany po włączeniu, albo właściwości nie "
            "zostały przeładowane). "
        ) + detail

    # v324: ten Termux w ogole nie ma RUN_COMMAND.
    #
    # ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-12 21:43, krok 3):
    #
    #   "Error type 3 / Error: Activity class
    #    {com.termux/com.termux.app.RunCommandActivity}
    #    does not exist."
    #
    # To nie jest kwestia allow-external-apps ani restartu — w tej
    # wersji Termuksa tej activity po prostu nie ma i zadna liczba
    # prob tego nie zmieni. A komenda, o ktora chodzilo ("sleep 5;
    # pm path org.linphone"), swietnie chodzi w naszym wlasnym
    # procesie. Wiec ja po prostu uruchamiamy i mowimy, co zrobilismy
    # — zamiast oddawac blad i patrzec, jak zespol szuka obejscia
    # przez dwa kroki.
    if (
        not started
        and "does not exist" in str(output)
    ):

        log(
            "ANDROID",
            "Ten Termux nie ma RunCommandActivity — osobnego okna "
            "nie otworze. Uruchamiam te komende u siebie."
        )

        zamiast = (
            termux_run_background(command)
            if background else termux_run(command)
        )

        if isinstance(zamiast, dict):
            zamiast["zamiast_nowego_okna"] = (
                "Ta wersja Termuksa nie ma okna RUN_COMMAND "
                "(Activity nie istnieje), więc uruchomiłem to samo "
                "u siebie. Wynik jest ten sam, tylko bez osobnego "
                "okna na ekranie."
            )

        return zamiast

    return {
        "ok": started,
        "action": "run_in_new_window",
        "command": command,
        "script": str(script_path),
        "background": bool(background),
        "needs_termux_restart": not already_enabled,
        "detail": detail
    }


def android_install_apk(path, reinstall=True):
    """
    Instaluje APK przez `adb install` i PARSUJE wynik zamiast
    zgadywać po returncode — `adb install` potrafi zwrócić
    returncode=0 nawet gdy instalacja faktycznie się nie powiodła
    (błąd jest tylko w tekście stdout, np.
    "INSTALL_FAILED_UPDATE_INCOMPATIBLE" albo
    "INSTALL_FAILED_VERSION_DOWNGRADE"). Wcześniej Gemini musiałoby
    to zgadywać przez surowe `shell("adb install ...")`.

    reinstall=True dodaje flagę -r (nadpisz istniejącą instalację,
    zachowując dane) — domyślne, bo to typowy przypadek przy
    iteracyjnym budowaniu tej samej aplikacji.
    """

    path = str(path or "").strip()

    if not path:
        return {
            "ok": False,
            "error": "Pusta ścieżka do APK."
        }

    flags = "-r" if reinstall else ""

    result = execute_shell(
        "adb install " + flags + " " + shlex.quote(path),
        timeout=90
    )

    output = (
        result.get("stdout", "")
        + result.get("stderr", "")
    )

    success = "Success" in output

    failure_match = re.search(
        r"(INSTALL_FAILED_[A-Z_]+)",
        output
    )

    return {
        "ok": success,
        "action": "install_apk",
        "path": path,
        "failure_reason": (
            failure_match.group(1) if failure_match else None
        ),
        "detail": short(output, 800)
    }


def android_uninstall_app(package):
    """
    Odinstalowuje aplikację po nazwie pakietu przez
    `adb uninstall`. Przydatne przed czystą reinstalacją, gdy
    android_install_apk zwróci błąd typu
    INSTALL_FAILED_UPDATE_INCOMPATIBLE (podpis/wersja niezgodne z
    poprzednią instalacją) — wtedy zwykłe -r nie wystarczy, trzeba
    najpierw odinstalować.
    """

    package = str(package or "").strip()

    if not package:
        return {
            "ok": False,
            "error": "Pusta nazwa pakietu."
        }

    result = execute_shell(
        "adb uninstall " + shlex.quote(package),
        timeout=30
    )

    output = (
        result.get("stdout", "")
        + result.get("stderr", "")
    )

    success = "Success" in output

    return {
        "ok": success,
        "action": "uninstall_app",
        "package": package,
        "detail": short(output, 500)
    }


def android_logcat(package=None, lines=200):
    """
    Zrzuca ostatnie wpisy logcat (adb logcat -d = zrzuć i wyjdź,
    NIE zawiesza się czekając na nowe logi) — kluczowe do
    diagnozowania APLIKACJI, KTÓRA SIĘ ZAINSTALOWAŁA, ALE PADA PRZY
    URUCHOMIENIU. Wcześniej agent nie miał ŻADNEGO sposobu, żeby
    zobaczyć crash stack trace — jedyne dostępne narzędzia
    (android_screenshot, android_state) nic nie pokażą, jeśli
    aplikacja zdąży się wywalić, zanim cokolwiek narysuje.

    Jeżeli podano `package`, filtruje po PID tego procesu (przez
    `adb shell pidof <package>`) — jeśli proces już nie działa
    (bo padł), logi PID-u nadal są w buforze logcat, więc to wciąż
    działa tuż po crashu.
    """

    lines = int(lines or 200)

    pid = None

    if package:

        package = str(package).strip()

        pid_result = execute_shell(
            "adb shell pidof " + shlex.quote(package),
            timeout=15
        )

        pid_out = pid_result.get("stdout", "").strip()

        if pid_out:
            pid = pid_out.split()[0]

    command = "adb logcat -d -t " + str(lines)

    if pid:
        command += " --pid=" + shlex.quote(pid)

    result = execute_shell(
        command,
        timeout=30
    )

    output = result.get("stdout", "")

    crashed = bool(
        re.search(
            r"FATAL EXCEPTION|AndroidRuntime.*FATAL",
            output
        )
    )

    return {
        "ok": result.get("ok", False),
        "action": "logcat",
        "package": package,
        "pid": pid,
        "crash_detected": crashed,
        "log": short(output, 6000)
    }


# ============================================================
# BEZPIECZEŃSTWO: POTWIERDZENIE PRZED USUWANIEM
# ============================================================
#
# Żadne narzędzie nie usuwało dotąd niczego bez pytania — Gemini
# mogło uruchomić `rm -rf cokolwiek` przez shell/termux_run bez
# żadnej bramki. Poniższe dwie funkcje to naprawiają: wykrywają
# komendy wyglądające na usuwanie i zatrzymują się, pytając
# operatora w terminalu, zanim cokolwiek faktycznie zniknie.
# ============================================================

_DELETE_COMMAND_PATTERN = re.compile(
    r"\b(rm|rmdir|unlink)\b|\bfind\b[^\n]*-delete\b",
    re.IGNORECASE
)


def _looks_like_delete_command(command):
    return bool(
        _DELETE_COMMAND_PATTERN.search(str(command or ""))
    )


# v365: NASZ WLASNY LOG Z TEGO BIEGU NIE WYMAGA PYTANIA.
#
# ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-16 22:39, krok 4).
# O 23:04:28 Gemini poprosilo o:
#
#     rm ~/krok1.log && termux-change-repo
#
# ~/krok1.log to byl NASZ wlasny bufor: zalozylismy go 40 sekund
# wczesniej jako log_file dla termux_run_background (23:01:31,
# pid 5538, `pkg update && pkg install ...`). Straznik zobaczyl
# `rm`, zablokowal i zapytal operatora w terminalu. Uzytkownik spal.
#
# Odpowiedz przyszla o 06:10:48 — po 7 godzinach i 6 minutach. Sama
# komenda wykonala sie potem w 0,3 s (duration_s: 0.3). Caly nocny
# bieg stal na pytaniu o skasowanie pliku, ktory sami zalozylismy.
#
# Nie oslabiamy straznika. Robimy jeden waski wyjatek, oparty na
# danych, ktore juz mamy: _logi_w_tle. Ten slownik zaklada sie
# WYLACZNIE w termux_run_background(), w chwili uruchomienia
# procesu, i zyje tylko w pamieci tego procesu — wiec log z
# POPRZEDNIEGO uruchomienia nigdy w nim nie jest.
#
# Warunki sa celowo ostre. Wyjatek dziala tylko, gdy KAZDY czlon
# komendy, ktory cokolwiek usuwa, to gole `rm` z samymi sciezkami,
# a KAZDA z tych sciezek jest dokladnie kluczem w _logi_w_tle.
# Odpadaja wiec: `rm -rf`, `rm -f`, jakakolwiek flaga, gwiazdki i
# inne wzorce powloki, `rmdir`, `unlink`, `find -delete`, pliki
# uzytkownika, sciezki nieznane i logi z wczesniejszych biegow.
#
# Czlonow, ktore NIC nie usuwaja (`&& termux-change-repo`), ten
# straznik nie ocenia — nigdy tego nie robil. On pilnuje usuwania.
_ZNAKI_WZORCA_POWLOKI = "*?[]{}$`"


def _sciezka_naszego_logu_z_tego_biegu(cel):
    """Czy ta sciezka to dokladnie nasz log_file z tego biegu."""

    cel = str(cel or "").strip().strip("'\"")

    if not cel:
        return False

    if any(z in cel for z in _ZNAKI_WZORCA_POWLOKI):
        return False

    # Tylda tylko na poczatku, jako $HOME — nigdzie indziej.
    if "~" in cel[1:]:
        return False

    # Sciezka musi byc ZAKOTWICZONA: "~/..." albo "/...".
    #
    # Gola nazwa wzgledna znaczy co innego dla nas niz dla powloki.
    # `cd /gdzies && rm krok1.log` — my rozwiazalibysmy to wzgledem
    # $HOME i znalezli nasz log w rejestrze, a powloka skasowalaby
    # /gdzies/krok1.log. Klucze w _logi_w_tle sa zawsze bezwzgledne,
    # wiec zadamy tego samego od sciezki w komendzie.
    if not (cel.startswith("~/") or cel.startswith("/")):
        return False

    try:
        return str(_resolve_home_relative_path(cel)) in _logi_w_tle
    except Exception:
        return False


def _usuwa_tylko_nasze_logi_z_tego_biegu(command):
    """
    Czy ta komenda usuwa WYLACZNIE nasze wlasne logi z tego biegu.

    Zwraca False przy najmniejszej watpliwosci — patrz komentarz
    wyzej. Wtedy obowiazuje dotychczasowe zabezpieczenie.
    """

    usuwajace = 0

    for czlon in re.split(r"[;&|]+|\n", str(command or "")):

        if not _DELETE_COMMAND_PATTERN.search(czlon):
            continue

        slowa = czlon.split()

        # Tylko gole `rm`. rmdir, unlink, `find ... -delete` i
        # wszystko, co ma `rm` gdzies dalej w czlonie — odpada.
        if len(slowa) < 2 or slowa[0] != "rm":
            return False

        for arg in slowa[1:]:

            if arg.startswith("-"):
                return False

            if not _sciezka_naszego_logu_z_tego_biegu(arg):
                return False

        usuwajace += 1

    return usuwajace > 0


def _confirm_destructive_action(description):
    """
    Blokuje i pyta operatora w terminalu, zanim agent wykona
    nieodwracalną operację (usunięcie pliku/katalogu).

    Zwraca True TYLKO przy jawnym potwierdzeniu. Każdy inny
    przypadek — odmowa, brak terminala (EOFError), Ctrl+C — jest
    traktowany jako odmowa. To bezpieczny domyślny wybór: agent
    może czasem niepotrzebnie zapytać (np. o nieszkodliwe "grep
    -rm" w komentarzu), ale nigdy nie usunie niczego bez pytania.
    """

    try:
        print()
        print("⚠️  AGENT CHCE WYKONAĆ OPERACJĘ USUWANIA:")
        print("   " + str(description))

        # Zaobserwowany realny incydent (POWTÓRZONY mimo wcześniejszej
        # łatki v49): użytkownik wpisał "t" na pytanie o reset sesji,
        # terminal POKAZAŁ "t", a program mimo to odczytał to jako
        # odmowę. Pierwsza próba naprawy (v49) drenowała bufor przez
        # `sys.stdin.readline()` w pętli — ale readline() BLOKUJE,
        # jeśli w buforze czeka NIEDOKOŃCZONY fragment (bez znaku
        # nowej linii, np. resztka wklejonego tekstu, której
        # użytkownik jeszcze nie "zamknął" enterem) — w tym stanie
        # KOLEJNE znaki, które użytkownik dopiero co wpisuje (prawdziwe
        # "t" + Enter), doklejają się do TEGO SAMEGO niedokończonego
        # fragmentu w buforze terminala, więc readline() zwraca
        # "resztka+t" zamiast samego "t" — terminal nadal POKAZUJE
        # wpisane "t" (lokalne echo terminala, niezależne od tego, co
        # faktycznie odczytał proces), ale porównanie z "t" już nie
        # przechodzi. Naprawione właściwym, atomowym narzędziem
        # systemowym do tego dokładnie przypadku: termios.tcflush()
        # kasuje WSZYSTKO, co czeka w buforze wejściowym terminala,
        # na poziomie kernela — bez ryzyka blokady na niedokończonej
        # linii, w przeciwieństwie do ręcznego drenażu przez readline().
        try:
            import termios
            termios.tcflush(sys.stdin.fileno(), termios.TCIFLUSH)
        except Exception:
            pass

        answer = input(
            "   Zezwolić? [t/N] > "
        ).strip().lower()

        return answer in ("t", "tak", "y", "yes")

    except (EOFError, KeyboardInterrupt):
        print()
        return False


# ------------------------------------------------------------
# Narzędzia Gemini/Pythona NIE SĄ plikami wykonywalnymi — nie
# istnieją w PATH Termuksa. Zaobserwowany, POWTARZAJĄCY SIĘ (v25,
# v35, v38 — trzy razy w coraz to innej postaci) wzorzec błędu:
# skrypt shell próbuje wywołać jedno z tych narzędzi bezpośrednio
# (`android_screenshot ...`) albo sprawdzić jego istnienie przez
# `command -v`/`which` — to ZAWSZE kończy się "nie znaleziono" i
# cichym przejściem na gorszy zamiennik (screencap/dumpsys), a nie
# realnym wywołaniem narzędzia. Zamiast łatać to w promptach za
# każdym razem, gdy pojawi się kolejny wariant (co robić przy
# BARDZIEJ złożonych zadaniach w przyszłości?) — blokujemy to
# STRUKTURALNIE, w kodzie, dla WSZYSTKICH tych nazw na raz, zanim
# taka komenda w ogóle zostanie wykonana. To działa niezależnie od
# tego, czy model "pamięta" regułę z promptu.
_GEMINI_ONLY_TOOL_NAMES = [
    "termux_mkdir", "termux_ls", "termux_write_file",
    "termux_read_file", "termux_run_background", "termux_processes",
    "termux_check_process", "termux_stop_process",
    "termux_start_second_session", "termux_file_exists",
    "termux_delete", "termux_check_apk", "termux_patch_file",
    "ask_deepseek",
    "chrome_tabs", "chrome_inspect", "chrome_open", "chrome_click",
    "chrome_type", "chrome_execute_js",
    "android_state", "android_click", "android_click_resource",
    "android_tap", "android_type", "android_press", "android_swipe",
    "android_long_click", "android_set_clipboard", "android_paste_text",
    "android_screenshot", "android_screenshot_ocr", "android_launch_app",
    "android_list_packages", "android_assert_text_visible",
    "android_run_in_new_window", "android_install_apk",
    "android_uninstall_app", "android_logcat",
]

_TOOL_NAMES_ALT = "|".join(
    re.escape(n)
    for n in sorted(
        _GEMINI_ONLY_TOOL_NAMES,
        key=len,
        reverse=True
    )
)

_FAKE_TOOL_EXISTENCE_CHECK_PATTERN = re.compile(
    r"\b(?:command\s+-v|which|type)\s+(" + _TOOL_NAMES_ALT + r")\b"
)

_FAKE_TOOL_BARE_INVOCATION_PATTERN = re.compile(
    r"^(?:if\s+|elif\s+|while\s+|!\s*)?(" + _TOOL_NAMES_ALT + r")\b"
)


def _looks_like_fake_tool_shell_invocation(command):
    """
    Wykrywa próbę wywołania narzędzia Gemini/Pythona jako polecenia
    powłoki (albo sprawdzenia go przez command -v/which) — analizuje
    KAŻDĄ linię osobno, bo to właśnie tak wygląda w realnych
    skryptach (jedna linia z `if command -v NAZWA`, inna z samym
    `NAZWA argumenty`). Zwraca nazwę wykrytego narzędzia albo None.
    """

    if not command:
        return None

    for line in str(command).splitlines():

        stripped = line.strip()

        if not stripped:
            continue

        match = _FAKE_TOOL_EXISTENCE_CHECK_PATTERN.search(stripped)

        if match:
            return match.group(1)

        match = _FAKE_TOOL_BARE_INVOCATION_PATTERN.match(stripped)

        if match:
            return match.group(1)

    return None


def _fake_tool_invocation_error(tool_name):
    return {
        "ok": False,
        "error": (
            "'" + tool_name + "' to narzędzie Gemini/Pythona, NIE "
            "polecenie powłoki — nie istnieje jako plik wykonywalny "
            "w PATH, więc command -v/which zawsze zwróci "
            "\"nie znaleziono\", a próba uruchomienia go w shellu "
            "zawsze się nie powiedzie. Wywołaj '" + tool_name + "' "
            "BEZPOŚREDNIO jako osobne, prawdziwe narzędzie Gemini — "
            "nie przez termux_run/termux_run_background/shell."
        ),
        "blocked_fake_tool_invocation": True
    }


# Zaobserwowany realny, wielokrotnie powtarzający się incydent:
# Gemini próbuje "przetestować" dopiero co napisane narzędzie z
# custom_tools/ przez `python -c "from agent.custom_tools.X import
# run; ..."`. To NIGDY nie może zadziałać niezależnie od __init__.py
# — `~/agent` zawiera PLIK `agent.py`, więc Python od razu traktuje
# "agent" jako zwykły MODUŁ (ten plik), nie jako pakiet z
# podkatalogami, i "agent.custom_tools" nie ma prawa się rozwiązać.
# Prompt-only ostrzeżenie (MAIN_PROMPT) okazało się niewystarczające
# — Gemini i tak próbowało tego kilka razy w jednym realnym
# przebiegu, marnując pełne cykle TASK-u na identyczny,
# przewidywalny błąd. Blokujemy to strukturalnie, z jasnym
# wyjaśnieniem DLACZEGO i co zrobić zamiast tego.
_CUSTOM_TOOL_SELF_TEST_IMPORT_PATTERN = re.compile(
    r"from\s+agent\.custom_tools\.[\w.]+\s+import"
)


# ============================================================
# SHELL
# ============================================================

def execute_shell(command, timeout=None):

    command = str(
        command or ""
    ).strip()

    if not command:
        return {
            "ok": False,
            "error": "Pusta komenda"
        }

    if _CUSTOM_TOOL_SELF_TEST_IMPORT_PATTERN.search(command):
        return {
            "ok": False,
            "error": (
                "Import 'from agent.custom_tools.X import ...' NIGDY "
                "nie zadziała z tego katalogu — '~/agent' zawiera "
                "PLIK agent.py, więc Python od razu traktuje 'agent' "
                "jako zwykły moduł (ten plik), nie jako pakiet z "
                "podkatalogami, niezależnie od __init__.py. Narzędzie "
                "z custom_tools/ jest już zarejestrowane AUTOMATYCZNIE "
                "od razu przy zapisie (termux_write_file) — wywołaj "
                "je BEZPOŚREDNIO jako zwykłe narzędzie w NASTĘPNEJ "
                "konsultacji, nie testuj go przez import w Pythonie."
            ),
            "command": command,
            "blocked_by_safety_gate": True
        }

    fake_tool = _looks_like_fake_tool_shell_invocation(command)

    if fake_tool:
        return _fake_tool_invocation_error(fake_tool)

    if (
        _looks_like_delete_command(command)
        and not _usuwa_tylko_nasze_logi_z_tego_biegu(command)
    ):

        if not _confirm_destructive_action(
            "Komenda usuwająca: " + command
        ):
            return {
                "ok": False,
                "error": (
                    "Operacja usuwania odrzucona (brak "
                    "potwierdzenia operatora). Jeżeli to "
                    "naprawdę potrzebne, zapytaj użytkownika "
                    "wprost i poczekaj na jego decyzję zamiast "
                    "ponawiać tę samą komendę."
                ),
                "command": command,
                "blocked_by_safety_gate": True
            }

    # v283: gdy wywolujacy nie narzucil limitu, dobieramy go do
    # tego, co ta komenda ma zrobic. Sondy po plikach wolaja z
    # timeout=15 i to zostaje bez zmian.
    if timeout:
        effective_timeout = int(timeout)
    elif _to_dluga_robota(command):
        effective_timeout = DLUGA_ROBOTA_TIMEOUT
        log(
            "TERMUX",
            "To jest robota na dluzej (pobieranie/kompilacja) — "
            "czekam do skutku, maks. "
            + str(DLUGA_ROBOTA_TIMEOUT // 60) + " min. Co "
            + str(PODGLAD_CO_SEKUND) + " s bede pisal, na czym stoi."
        )
    else:
        effective_timeout = COMMAND_TIMEOUT

    started = datetime.now()

    try:

        # BEZ `cwd=` TU: subprocess dziedziczy katalog roboczy PROCESU
        # agent.py — czyli tam, skąd użytkownik uruchomił `python
        # agent.py` (np. `~/agent`, jeśli stamtąd odpalił skrypt), a
        # NIE koniecznie `~`. Zaobserwowany realny bug (log
        # 2026-08-30): skrypt napisał `open('plik.txt', 'w')` (goła,
        # względna nazwa — bez `~/`) i faktycznie zapisał plik, ale
        # POD ~/agent/plik.txt, nie ~/plik.txt. Kolejny krok próbował
        # go odczytać przez `termux_read_file("~/plik.txt")` (zespół
        # zakłada, że "goła nazwa pliku" = katalog domowy) i dostał
        # "Plik nie istnieje" — mimo że plik fizycznie ISTNIAŁ, tylko
        # gdzie indziej. Zespół stracił kilka kroków, próbując
        # "znaleźć" dane, które od początku były na dysku. Pinujemy
        # katalog roboczy WPROST na `~`, żeby goła względna nazwa
        # pliku w KAŻDYM poleceniu powłoki (termux_run) zawsze
        # lądowała tam, gdzie zespół i tak zakłada — niezależnie od
        # tego, z jakiego katalogu faktycznie wystartował sam
        # agent.py.
        # v198 -- zaobserwowany realny bug (log 2026-09-04, v197).
        # Bartek napisal skrypt z `read -p "Podaj klucz API: "`, a
        # capture_output=True NIE przekierowuje stdin -- podproces
        # dziedziczyl wiec TERMINAL UZYTKOWNIKA. `read` albo kradl
        # wejscie przeznaczone dla samego agenta (ten sam stdin, na
        # ktorym agent robi input()/_read_full_input), albo wisial do
        # konca timeoutu. Oba warianty sa ciche i mylace.
        #
        # stdin=DEVNULL: `read` dostaje EOF NATYCHMIAST, skrypt konczy
        # sie od razu i czytelnie, a terminal uzytkownika zostaje
        # nietkniety. Wykonawca i tak nie ma klawiatury -- udawanie,
        # ze ma, moglo tylko zaszkodzic.
        # v288: dluga robota leci z podgladem — patrz
        # _uruchom_z_podgladem().
        # v292: a od teraz leca TAMTEDY WSZYSTKIE komendy. Nie dla
        # podgladu (ten dalej wlacza sie tylko przy dlugim limicie),
        # tylko dlatego, ze capture_output=True czekalo na EOF na
        # potoku — czyli na kazdy proces puszczony w tle przez `&`,
        # nawet gdy sam skrypt dawno sie skonczyl. Piecosekundowy
        # skrypt nagrywajacy potrafil przez to wisiec pelne 120 s i
        # wrocic jako "Timeout". Cala reszta programu dostaje
        # dokladnie ten sam slownik co dotad.
        return _uruchom_z_podgladem(
            command, effective_timeout, started
        )

    except subprocess.TimeoutExpired as e:

        # WAŻNE: TimeoutExpired NIESIE ze sobą to, co proces
        # zdążył wypisać przed zabiciem (jeśli capture_output=True).
        # Wcześniej ta informacja była bezpowrotnie tracona —
        # dokładnie to widać w logach ("Timeout" i nic więcej).

        partial_stdout = getattr(e, "stdout", None)
        partial_stderr = getattr(e, "stderr", None)

        if isinstance(partial_stdout, bytes):
            partial_stdout = partial_stdout.decode(
                "utf-8", errors="replace"
            )

        if isinstance(partial_stderr, bytes):
            partial_stderr = partial_stderr.decode(
                "utf-8", errors="replace"
            )

        # v293: dlaczego przerwalismy — "stoi", "sufit" albo
        # "w kolko". Samo slowo "Timeout" kazalo zespolowi zgadywac
        # i zwykle zgadywal zle (log 2026-09-09: caly przeglad kodu
        # o objawie, ktorego nie bylo).
        return {
            "ok": False,
            "error": "Timeout",
            "powod": getattr(e, "powod", ""),
            "co_sie_stalo": getattr(e, "szczegol", ""),
            "command": command,
            "timeout": effective_timeout,
            "duration_s": round(
                (datetime.now() - started).total_seconds(),
                1
            ),
            "stdout_partial": short(partial_stdout or "", 4000),
            "stderr_partial": short(partial_stderr or "", 4000)
        }

    except Exception as e:

        return {
            "ok": False,
            "error": str(e),
            "command": command,
            "timeout": effective_timeout
        }


# ============================================================
# CHROME
# ============================================================

# Zaobserwowany realny problem: gdy CDP raz się zepsuje w trakcie
# celu (np. karta Chrome nawiguje gdzie indziej/proces pada),
# chrome_summary() wywoływane RAZ NA KROK i tak zawsze próbuje
# ensure_chrome_cdp_forward() od nowa z pełnymi 3 próbami x 1s
# przerwy — kilka sekund straconych na każdym KOLEJNYM kroku, mimo
# że wynik ("Brak dostępnych kart Chrome/CDP") jest z góry znany.
# Licznik porażek z rzędu ogranicza liczbę prób po 2. porażce,
# zamiast przestać próbować całkowicie — telefon może w
# międzyczasie odzyskać CDP (np. użytkownik ręcznie otworzy kartę).
_CDP_CONSECUTIVE_FAILURES = 0


def ensure_chrome_cdp_forward(retries=3):
    """
    Ustawia `adb forward` dla CDP i sprawdza /json/version.

    WAŻNE: urządzenie jest szukane przez find_adb(), które samo
    próbuje automatycznego reconnectu (adb_try_connect) na ostatnio
    skonfigurowany adres WiFi, gdy `adb devices` nic nie zwróci —
    to naprawia najczęstszą przyczynę "brak urządzenia" po
    restarcie WiFi na telefonie.

    Druga częsta usterka to przejściowy błąd samego requestu HTTP
    zaraz po (re)ustawieniu forwardu — ADB/atx-agent/Chrome
    potrzebuje chwili, żeby transport wstał, i wtedy
    RemoteDisconnected("Remote end closed connection without
    response") jest zwykle jednorazowym zacięciem, nie trwałą
    awarią. Dlatego cały blok forward+request jest powtarzany do
    `retries` razy z krótką przerwą, zamiast poddawać się od razu.

    Po 2 porażkach Z RZĘDU liczba prób jest ograniczana do 1 (bez
    utraty samej zdolności do wykrycia powrotu CDP) — patrz
    _CDP_CONSECUTIVE_FAILURES powyżej.
    """

    global _CDP_CONSECUTIVE_FAILURES

    if _CDP_CONSECUTIVE_FAILURES >= 2:
        retries = 1

    device = find_adb()

    if not device:
        log("CHROME", "ADB: brak urządzenia")
        _CDP_CONSECUTIVE_FAILURES += 1
        return False

    log("CHROME", f"ADB device: {device}")

    last_error = None

    for attempt in range(1, retries + 1):

        try:

            subprocess.run(
                [
                    "adb",
                    "-s",
                    device,
                    "forward",
                    "--remove",
                    f"tcp:{CDP_PORT}"
                ],
                capture_output=True,
                text=True,
                timeout=5
            )

            proc = subprocess.run(
                [
                    "adb",
                    "-s",
                    device,
                    "forward",
                    f"tcp:{CDP_PORT}",
                    "localabstract:chrome_devtools_remote"
                ],
                capture_output=True,
                text=True,
                timeout=8
            )

            if proc.returncode != 0:
                last_error = (
                    "ADB forward ERROR: "
                    + (proc.stderr.strip() or "unknown error")
                )
                log("CHROME", last_error)
                time.sleep(1)
                continue

            log(
                "CHROME",
                f"ADB forward OK -> tcp:{CDP_PORT}"
            )

            r = requests.get(
                f"http://{CDP_HOST}:{CDP_PORT}/json/version",
                timeout=5
            )

            r.raise_for_status()

            info = r.json()

            log(
                "CHROME",
                "CDP OK -> "
                + str(info.get("Browser", "Chrome"))
            )

            _CDP_CONSECUTIVE_FAILURES = 0

            return True

        except Exception as e:

            last_error = str(e)

            log(
                "CHROME",
                f"CDP próba {attempt}/{retries} nieudana: "
                + last_error
            )

            time.sleep(1)

            # Urządzenie mogło zniknąć w międzyczasie (WiFi) —
            # spróbuj je odnaleźć/reconnect na kolejną próbę.
            refreshed = find_adb()

            if refreshed:
                device = refreshed

    log(
        "CHROME",
        f"CDP AUTO ERROR (po {retries} próbach): {last_error}"
    )

    _CDP_CONSECUTIVE_FAILURES += 1

    return False


def chrome_tabs():

    if not ensure_chrome_cdp_forward():
        return []

    try:

        r = requests.get(
            f"http://{CDP_HOST}:{CDP_PORT}/json",
            timeout=5
        )

        r.raise_for_status()

        data = r.json()

        result = []

        for tab in data:

            if (
                tab.get("type") == "page"
                and tab.get(
                    "webSocketDebuggerUrl"
                )
            ):

                result.append({
                    "id":
                        tab.get("id", ""),
                    "title":
                        tab.get("title", ""),
                    "url":
                        tab.get("url", ""),
                    "webSocketDebuggerUrl":
                        tab.get(
                            "webSocketDebuggerUrl"
                        )
                })

        return result

    except Exception:

        return []


def chrome_summary():

    tabs = chrome_tabs()

    if not tabs:
        return "Brak dostępnych kart Chrome/CDP."

    lines = []

    for tab in tabs:

        lines.append(
            f"[{tab['id']}] "
            f"{short(tab['title'], 100)} | "
            f"{short(tab['url'], 300)}"
        )

    return "\n".join(lines)


def _ta_sama_strona(a, b):
    """
    Czy dwa adresy prowadza do tego samego miejsca — z pominieciem
    kotwicy (#...) i koncowego ukosnika. Query zostaje, bo czesto
    niesie tresc (?frameUrl=..., ?id=...).
    """

    def _oczysc(u):
        u = str(u or "").strip()
        u = u.split("#", 1)[0]
        return u.rstrip("/").lower()

    a, b = _oczysc(a), _oczysc(b)

    return bool(a) and a == b


def _karta_z_tym_adresem(url):
    """Otwarta karta pokazujaca juz ten adres, albo None."""

    try:
        for karta in chrome_tabs():
            if _ta_sama_strona(karta.get("url"), url):
                return karta
    except Exception:
        pass

    return None


def _przelacz_na_karte(tab_id):
    """
    Wyciaga karte na wierzch przez CDP. True, gdy sie udalo.

    ZAOBSERWOWANY REALNY PRZYPADEK (log 2026-09-06, KROKI 8-14).
    Kazde `termux-open-url` otwieralo NOWA karte, choc ta sama strona
    juz wisiala. Po siedmiu krokach Chrome miał cztery karty Twilio,
    dwie z nich identyczne (AC18e2...), i zespol za kazdym razem
    zgadywal, na ktorej pracuje. To samo widac w logu z 11:58, gdzie
    byly TRZY karty dashboard.vapi.ai/phone-numbers naraz.
    """

    if not ensure_chrome_cdp_forward():
        return False

    try:
        r = requests.get(
            "http://" + CDP_HOST + ":" + str(CDP_PORT)
            + "/json/activate/" + str(tab_id),
            timeout=5
        )
        return r.status_code == 200

    except Exception:
        return False


def find_tab(
    tab_id=None,
    contains=None
):

    tabs = chrome_tabs()

    if tab_id:

        for tab in tabs:

            if tab["id"] == str(tab_id):
                return tab

    if contains:

        needle = str(
            contains
        ).lower()

        for tab in tabs:

            value = (
                tab["title"]
                + " "
                + tab["url"]
            ).lower()

            if needle in value:
                return tab

    # Zaobserwowany realny problem: chrome_open/chrome_click/
    # chrome_type mają tab_id/contains jako OPCJONALNE parametry w
    # schemacie narzędzia (gemini_tools()) — Gemini w praktyce
    # prawie zawsze woła je z SAMYM url/text, bez tab_id/contains
    # (nie zna z góry opaque tab_id, a rzadko podaje contains, gdy
    # nic go o tym nie uprzedza). Bez tej reguły find_tab(None,
    # None) zwracał None BEZWARUNKOWO, więc chrome_open zawodziło
    # ZAWSZE — nawet gdy istniała dokładnie jedna, oczywista karta
    # do użycia ("[831] Nowa karta"). Gdy jest dokładnie jedna
    # karta, nie ma żadnej niejednoznaczności — użyj jej.
    if not tab_id and not contains and len(tabs) == 1:
        return tabs[0]

    return None


# Na wyraźną prośbę użytkownika (2026-08-28): najsłabszym punktem
# obsługi Chrome był NASZ WŁASNY, ręcznie pisany JSON-RPC po surowym
# websockecie — to tam realnie pojawiały się błędy w logach ("CDP
# próba 1/3 nieudana", "CDP niedostępne"). Sprawdzone PRZED
# wdrożeniem (nauczka z pomyłki przy pydantic): `pychrome` używa
# WYŁĄCZNIE `requests` i `websocket-client` — tych samych dwóch
# bibliotek, których ten plik już używa — więc zero nowego ryzyka
# platformowego na Termux (w odróżnieniu od np. Playwrighta, który
# oficjalnie NIE wspiera Androida).
#
# `cdp_connect()`/`cdp_call()` zachowują DOKŁADNIE ten sam kontrakt
# co wcześniej (ten sam zwracany kształt, to samo `ws.close()` w
# `finally` u wywołujących) — dzięki temu chrome_eval() i chrome_open()
# (jedyne dwa miejsca, które ich bezpośrednio używają) NIE MUSIAŁY
# zostać w ogóle zmienione. `_PychromeConnection` to cienki wrapper
# zapewniający zgodność z `ws.close()`, którego wywołujący już
# oczekują, mimo że pychrome.Tab ma metodę `stop()`, nie `close()`.
class _PychromeConnection:

    def __init__(self, tab):
        self._tab = tab

    def close(self):
        try:
            self._tab.stop()
        except Exception:
            pass


def cdp_connect(tab):

    try:

        pychrome_tab = pychrome.Tab(**tab)
        pychrome_tab.start()

        return _PychromeConnection(pychrome_tab)

    except Exception as e:

        log(
            "CHROME",
            "CDP ERROR: " + str(e)
        )

        return None


def cdp_call(
    ws,
    msg_id,
    method,
    params=None,
    timeout=20
):

    try:

        result = ws._tab.call_method(
            method,
            _timeout=timeout,
            **(params or {})
        )

        return {
            "ok": True,
            "result": result
        }

    except Exception as e:

        return {
            "ok": False,
            "error": str(e)
        }


def chrome_eval(
    tab,
    javascript,
    timeout=20
):

    ws = cdp_connect(tab)

    if ws is None:
        return {
            "ok": False,
            "error": "CDP connect failed"
        }

    try:

        result = cdp_call(
            ws,
            1,
            "Runtime.evaluate",
            {
                "expression":
                    javascript,
                "returnByValue":
                    True,
                "awaitPromise":
                    True
            },
            timeout=timeout
        )

    finally:

        try:
            ws.close()
        except Exception:
            pass

    if not result.get("ok"):
        return result

    return (
        result
        .get("result", {})
        .get("result", {})
        .get("value")
    )


# ============================================================
# CHROME INSPECT
# ============================================================

# Ile najdluzej czekamy, az strona sama sie dokona. Nie jest to
# sztywna pauza — patrz _poczekaj_az_strona_dojdzie().
CHROME_LOAD_BUDGET_S = 8.0


def _poczekaj_az_strona_dojdzie(tab, budzet_s=CHROME_LOAD_BUDGET_S):
    """
    Czeka, az karta przestanie sie ladowac — i ANI CHWILI DLUZEJ.
    Zwraca liczbe sekund, ktore faktycznie zeszly (0.0, gdy strona
    byla gotowa od razu).

    ZAOBSERWOWANY REALNY PRZYPADEK (log 2026-09-06, KROK 2). Gemini
    otworzylo /dashboard/call-logs, natychmiast zrobilo
    chrome_inspect i dostalo cala tresc strony w postaci jednego
    slowa: "Loading...". Klikalo dalej w cos, czego jeszcze nie bylo,
    a potem szukalo wpisu polaczenia na liscie, ktora sie nie
    zdazyla wyrenderowac — i zameldowalo, ze polaczenia nie ma.
    Wniosek byl falszywy, a wyciagnal go z pustego ekranu.

    Sztywne "poczekaj 5 sekund" po kazdym kliknieciu byloby lekiem
    gorszym od choroby: przy kilkudziesieciu wywolaniach na cel
    zabiera minuty, w wiekszosci na strony, ktore byly gotowe od
    razu. Wiec pytamy strony, czy skonczyla, kilka razy na sekunde,
    i wracamy w tej samej chwili, w ktorej skonczyla. Typowo kosztuje
    to zero, przy wolnym panelu ulamek sekundy.
    """

    sonda = (
        "(() => ({"
        " gotowa: document.readyState === 'complete',"
        " tresc: (document.body ? document.body.innerText : '')"
        ".replace(/\\s+/g, ' ').trim().length"
        "}))()"
    )

    koniec = time.time() + max(0.0, float(budzet_s))
    start = time.time()

    while True:

        stan = chrome_eval(tab, sonda)

        if not isinstance(stan, dict):
            break

        # Gotowa i cos juz na niej jest. Sama flaga readyState nie
        # wystarcza: panele w Reakcie melduja "complete", majac na
        # ekranie samo "Loading..." (13 znakow).
        if stan.get("gotowa") and int(stan.get("tresc") or 0) > 40:
            break

        if time.time() >= koniec:
            break

        time.sleep(0.35)

    return round(time.time() - start, 2)


def chrome_inspect(
    tab_id=None,
    contains=None
):

    tab = find_tab(
        tab_id,
        contains
    )

    if tab is None:

        return {
            "ok": False,
            "error":
                "Nie znaleziono istniejącej karty"
        }

    _czekalismy = _poczekaj_az_strona_dojdzie(tab)

    javascript = r"""
(() => {

    const clean = (v) =>
        (v || "")
        .replace(/\s+/g, " ")
        .trim();

    const controls = [];

    document.querySelectorAll(
        'a,button,input,textarea,select,' +
        '[role="button"],' +
        '[contenteditable="true"]'
    ).forEach((el, index) => {

        const r =
            el.getBoundingClientRect();

        if (
            r.width <= 0 ||
            r.height <= 0
        ) {
            return;
        }

        controls.push({
            i: index,
            tag: el.tagName,
            text: clean(
                el.innerText ||
                el.value ||
                el.getAttribute(
                    "aria-label"
                )
            ),
            id: el.id || "",
            role:
                el.getAttribute(
                    "role"
                ) || "",
            href:
                el.href || "",
            type:
                el.getAttribute(
                    "type"
                ) || "",
            x:
                Math.round(r.x),
            y:
                Math.round(r.y),
            width:
                Math.round(r.width),
            height:
                Math.round(r.height)
        });

    });

    return {
        title:
            document.title,

        url:
            location.href,

        text:
            clean(
                document.body
                    ? document.body.innerText
                    : ""
            ).slice(
                0,
                10000
            ),

        controls:
            controls.slice(
                0,
                120
            )
    };

})()
"""

    value = chrome_eval(
        tab,
        javascript
    )

    if not isinstance(value, dict):

        return {
            "ok": False,
            "error": "Brak danych strony"
        }

    return {
        "ok": True,
        "tab_id":
            tab["id"],
        "title":
            value.get(
                "title",
                ""
            ),
        "url":
            value.get(
                "url",
                ""
            ),
        "text":
            short(
                value.get(
                    "text",
                    ""
                ),
                CHROME_TEXT_LIMIT
            ),
        "controls":
            value.get(
                "controls",
                []
            ),
        # Mowimy o tym tylko wtedy, gdy naprawde trzeba bylo poczekac
        # — inaczej byloby to pole-szum w kazdym wyniku.
        **(
            {"czekalem_na_zaladowanie_s": _czekalismy}
            if _czekalismy else {}
        )
    }


# ============================================================
# CHROME NAVIGATE
# ============================================================

CDP_403 = False

# ============================================================
# PAMIEC I MIERNIK STANU PRZEGLADARKI (v367)
# ============================================================
#
# ZAOBSERWOWANY REALNY BIEG (2026-09-17 16:42). Trzy rzeczy naraz:
#
#   1. W jednym kroku powstalo szesc kart: 1305, 1306, 1307, 1308,
#      1309, 1311 — w tym dwie pary tej samej strony. Mechanizm
#      "juz_otwarta" istnieje od dawna, ale w chrome_open pytal o
#      karte TYLKO wtedy, gdy nikt nie podal tab_id. Ostatnie
#      wywolanie podalo tab_id=1307, ta karta juz nie pokazywala tej
#      strony, wiec poszlismy prosto do `am start` — i zrobilismy
#      1311, choc ten sam adres wisial obok.
#
#   2. chrome_open("/dashboard") i chrome_open("/sign-in") wrocily
#      z "ok": true, a strony mialy tytul "Not found | Daily".
#      Sukces WYWOLANIA to nie sukces OPERACJI — dokladnie ta sama
#      pomylka, ktora v366 naprawil dla klikania.
#
#   3. Gemini czytalo strone przez document.body.innerText i
#      dostawalo najpierw baner ciasteczek ("This website stores
#      cookies on your machine..."), a nie tresc strony. Na kazdej
#      karcie, za kazdym razem.
#
# Nie dokladamy Gemini promptu i nie narzucamy kolejnosci narzedzi.
# Python ma byc jego PAMIECIA i MIERNIKIEM: pamietac, co juz bylo,
# i mowic, co naprawde sie stalo.

# Ile roznych akcji z rzedu bez zadnej zmiany stanu = brak postepu.
_CHROME_BRAK_POSTEPU_PROG = 4

def _chrome_stan_sie_zmienil(przed, po):
    """Czy miedzy dwoma stanami strony cokolwiek drgnelo."""

    if not przed or not po:
        return False

    if przed.get("href") != po.get("href"):
        return True

    if przed.get("title") != po.get("title"):
        return True

    try:
        return abs(
            int(po.get("znakow") or 0)
            - int(przed.get("znakow") or 0)
        ) > 40
    except Exception:
        return False


# Znaczniki, ktore w ID albo klasie elementu oznaczaja zgode na
# ciasteczka. Szukamy ich w STRUKTURZE, nie w tekscie — strona o
# polityce prywatnosci ma slowo "cookie" w tresci i ma prawo miec.
_ZNACZNIKI_BANERA_COOKIES = (
    "cookie", "consent", "gdpr", "cmp-", "onetrust", "truste",
    "privacy-banner", "hs-eu"
)


def _tresc_strony(tab, limit=4000):
    """
    Tresc strony z oddzielonym banerem ciasteczek.

    Zwraca {"page_content": ..., "cookie_notice": ...} albo None.

    ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-17 16:42).
    document.body.innerText na dashboard.daily.co zaczynalo sie od
    "This website stores cookies on your machine. These cookies are
    used to collect information about how you interact with our
    website and allow us to remember you..." — i to szlo do Gemini
    jako "tresc strony", na kazdej karcie, w kazdym kroku.

    Baner poznajemy po ID/klasie kontenera, nie po slowie w tekscie,
    i tylko wtedy, gdy trzyma mniej niz 40% tekstu strony. Dzieki
    temu strona O ciasteczkach zostaje strona o ciasteczkach.
    """

    znaczniki = json.dumps(
        list(_ZNACZNIKI_BANERA_COOKIES),
        ensure_ascii=False
    )

    javascript = """
(() => {

    const MARKERY = __MARKERY__;

    const clean = (v) =>
        (v || "").replace(/\\s+/g, " ").trim();

    const body = document.body;

    if (!body) {
        return { page_content: "", cookie_notice: "" };
    }

    const calosc = clean(body.innerText).length || 1;

    const czyBaner = (el) => {

        const opis = (
            (el.id || "") + " " +
            (typeof el.className === "string" ? el.className : "")
        ).toLowerCase();

        if (!MARKERY.some(m => opis.includes(m))) {
            return false;
        }

        // Kontener trzymajacy wiekszosc tekstu strony to nie baner,
        // tylko sama strona — np. polityka prywatnosci.
        const ile = clean(el.innerText).length;

        return ile > 0 && (ile / calosc) < 0.4;
    };

    const banery = [];

    document.querySelectorAll(
        'div,section,aside,dialog,[role="dialog"]'
    ).forEach(el => {
        if (czyBaner(el) && !banery.some(b => b.contains(el))) {
            banery.push(el);
        }
    });

    const wBanerze = (el) =>
        banery.some(b => b === el || b.contains(el));

    // Tresc wlasciwa: najpierw main/article, potem cale body.
    let zrodlo =
        document.querySelector('main') ||
        document.querySelector('[role="main"]') ||
        document.querySelector('article') ||
        body;

    const kawalki = [];
    const dodaj = (t) => {
        t = clean(t);
        if (t && kawalki.indexOf(t) === -1) {
            kawalki.push(t);
        }
    };

    zrodlo.querySelectorAll(
        'h1,h2,h3,h4,p,li,td,th,label,legend,summary'
    ).forEach(el => {
        if (!wBanerze(el)) {
            dodaj(el.innerText);
        }
    });

    if (!kawalki.length) {
        // Strona bez zadnej z tych struktur — bierzemy caly tekst
        // poza banerem, zamiast oddawac pustke.
        const klon = zrodlo.cloneNode(true);
        klon.querySelectorAll(
            'div,section,aside,dialog,[role="dialog"]'
        ).forEach(el => {
            const opis = (
                (el.id || "") + " " +
                (typeof el.className === "string" ? el.className : "")
            ).toLowerCase();
            if (MARKERY.some(m => opis.includes(m))) {
                el.remove();
            }
        });
        dodaj(klon.innerText);
    }

    const kontrolki = [];

    zrodlo.querySelectorAll(
        'a,button,input,textarea,select,[role="button"]'
    ).forEach(el => {
        if (wBanerze(el)) { return; }
        const etykieta = clean(
            el.innerText || el.value ||
            el.getAttribute("aria-label") ||
            el.getAttribute("placeholder")
        );
        if (!etykieta) { return; }
        const rodzaj = el.tagName.toLowerCase();
        const wpis =
            rodzaj === "a"
                ? ("link: " + etykieta)
                : (rodzaj === "input" || rodzaj === "textarea" ||
                   rodzaj === "select")
                    ? ("pole: " + etykieta)
                    : ("przycisk: " + etykieta);
        if (kontrolki.indexOf(wpis) === -1) {
            kontrolki.push(wpis);
        }
    });

    return {
        page_content: kawalki.join("\\n"),
        controls: kontrolki,
        cookie_notice: banery.map(b => clean(b.innerText)).join(" "),
        cookie_banners: banery.length
    };

})()
""".replace("__MARKERY__", znaczniki)

    try:

        wynik = chrome_eval(tab, javascript)

        if not isinstance(wynik, dict):
            return None

        tresc = str(wynik.get("page_content") or "")
        baner = str(wynik.get("cookie_notice") or "")

        out = {
            "page_content": short(tresc, limit)
        }

        if wynik.get("controls"):
            out["controls"] = list(wynik["controls"])[:40]

        if baner:
            # Idzie OSOBNO i krotko — zespol ma wiedziec, ze baner
            # jest (bo moze zaslaniac klikanie), ale nie czytac go
            # zamiast strony.
            out["cookie_notice"] = short(baner, 200)

        return out

    except Exception:
        return None


# Jednoznaczne slady strony, ktorej nie ma. Szukamy ich w TYTULE
# albo na samym POCZATKU tresci — nie gdziekolwiek w tekscie, zeby
# artykul o bledach 404 nie zostal uznany za blad 404.
_SLADY_BRAKU_STRONY = (
    "404", "not found", "page not found", "nie znaleziono",
    "strona nie istnieje", "nie ma takiej strony",
)


def _strona_nie_istnieje(stan, tresc=None):
    """
    Czy ta strona jednoznacznie mowi, ze jej nie ma.

    Zwraca krotki dowod (tekst, na ktorym opieramy wniosek) albo
    None. Celowo ostroznie: tytul albo pierwsze 200 znakow tresci.
    """

    if not stan:
        return None

    tytul = str(stan.get("title") or "").strip()
    tytul_maly = tytul.lower()

    for slad in _SLADY_BRAKU_STRONY:
        if slad in tytul_maly:
            return "tytuł strony: " + tytul

    # Tresc jest slabszym sygnalem niz tytul, wiec pytamy waziej:
    # strona musi ZACZYNAC sie od takiego komunikatu. "Witamy w
    # pomocy. Jesli widzisz 404, napisz do nas" to nie jest strona
    # 404 — to strona, ktora o niej wspomina.
    poczatek = ""

    if isinstance(tresc, dict):
        poczatek = str(tresc.get("page_content") or "").strip()

    naglowek = poczatek[:25].lower()

    for slad in _SLADY_BRAKU_STRONY:
        if slad in naglowek:
            return "strona zaczyna się od: " + short(poczatek, 120)

    return None


def _chrome_snapshot(tab, akcja=None, stan=None, tresc=None):
    """
    Maly, spojny stan przegladarki — tyle, zeby Gemini nie musialo
    dopytywac osobnym wywolaniem o window.location.href ani o to,
    ktore karty sa otwarte.

    Zadnego DOM-u, zadnych powtorzen.
    """

    snap = {}

    try:
        karty = chrome_tabs()
    except Exception:
        karty = []

    if stan is None:
        stan = _stan_strony(tab)

    if stan:
        snap["active_tab"] = {
            "tab_id": (tab or {}).get("id"),
            "url": stan.get("href"),
            "title": stan.get("title")
        }

    if karty:
        snap["open_tabs"] = [
            {
                "tab_id": k.get("id"),
                "url": short(str(k.get("url") or ""), 120),
                "title": short(str(k.get("title") or ""), 80)
            }
            for k in karty[:12]
        ]

    if akcja:
        snap["last_action"] = str(akcja)

    if tresc:
        if tresc.get("page_content"):
            snap["page_content"] = tresc["page_content"]
        if tresc.get("controls"):
            snap["controls"] = tresc["controls"]
        if tresc.get("cookie_notice"):
            snap["cookie_notice"] = tresc["cookie_notice"]

    return snap


def _zaloguj_operacje_chrome(
    akcja, przed, po, zmienilo,
    karta_uzyta_ponownie=False,
    nowa_karta=False,
    brak_strony=None,
    sygnal=None
):
    """Jedna linia w logu na operacje — bez DOM-u."""

    czesci = ["action=" + short(str(akcja), 70)]

    if przed:
        czesci.append("before=" + short(str(przed.get("href") or ""), 60))

    if po:
        czesci.append("after=" + short(str(po.get("href") or ""), 60))

    czesci.append("state_changed=" + ("tak" if zmienilo else "NIE"))

    if karta_uzyta_ponownie:
        czesci.append("reused_existing_tab=tak")

    if nowa_karta:
        czesci.append("created_new_tab=tak")

    if brak_strony:
        czesci.append("page_not_found=tak")

    if sygnal:
        czesci.append(str(sygnal).lower() + "=tak")

    log("CHROME", " | ".join(czesci))


def _chrome_open_wynik(
    tab,
    url,
    czekalismy=None,
    metoda=None,
    juz_otwarta=False,
    nowa_karta=False,
    message=None
):
    """
    Jedno miejsce, w ktorym chrome_open odpowiada — zeby kazda z
    jego trzech drog (istniejaca karta, CDP, am start) mowila to
    samo i tak samo.

    v367: "ok": true znaczylo dotad tylko tyle, ze WYWOLANIE sie
    udalo. W biegu 2026-09-17 16:42 chrome_open("/dashboard") i
    chrome_open("/sign-in") wrocily z sukcesem, a strony mialy tytul
    "Not found | Daily". Zespol dostawal zielone swiatlo na strone,
    ktorej nie ma. Teraz patrzymy, co naprawde sie otworzylo.
    """

    stan = _stan_strony(tab)
    tresc = _tresc_strony(tab)

    wynik = {
        "ok": True,
        "tab_id": (tab or {}).get("id"),
        "url": (stan or {}).get("href") or str(url),
        "title": (stan or {}).get("title") or (tab or {}).get("title")
    }

    if czekalismy:
        wynik["czekalem_na_zaladowanie_s"] = czekalismy

    if metoda:
        wynik["method"] = metoda

    if juz_otwarta:
        wynik["juz_otwarta"] = True

    if message:
        wynik["message"] = message

    _brak = _strona_nie_istnieje(stan, tresc)

    if _brak:

        wynik["ok"] = False
        wynik["error"] = "page_not_found"
        wynik["dowod"] = _brak
        wynik["message"] = (
            "Adres sie otworzyl, ale tej strony tam nie ma ("
            + _brak + "). To nie jest blad przegladarki — ten "
            "konkretny URL nie istnieje. Zgadywanie kolejnych "
            "sciezek zwykle konczy sie tak samo; pewniejsze jest "
            "przejscie ze strony, ktora dziala."
        )

    snap = _chrome_snapshot(
        tab,
        akcja="open " + short(str(url), 80),
        stan=stan,
        tresc=tresc
    )

    if snap:
        wynik["snapshot"] = snap

    # v377: o tym, czy krecimy sie w kolko, mowi teraz wspolny rdzen
    # TARGET_STATE — w tym samym miejscu, co dla Termuxa, Androida i
    # procesow. chrome_open juz zwraca "url" i "title", wiec rdzen ma
    # z czego wziac cel i stan; nic tu nie dokladamy.
    _zaloguj_operacje_chrome(
        "open " + short(str(url), 80),
        None,
        stan,
        True,
        karta_uzyta_ponownie=juz_otwarta,
        nowa_karta=nowa_karta,
        brak_strony=_brak
    )

    return wynik


def chrome_open(
    url,
    tab_id=None,
    contains=None
):

    # Ta strona moze juz gdzies wisiec. Wtedy jej nie otwieramy drugi
    # raz — wyciagamy istniejaca karte na wierzch. Patrz
    # _przelacz_na_karte().
    if not tab_id and not contains:

        _juz = _karta_z_tym_adresem(url)

        if _juz is not None:

            _przelacz_na_karte(_juz["id"])
            _czekalismy = _poczekaj_az_strona_dojdzie(_juz)

            log(
                "CHROME",
                "Ta strona juz byla otwarta — przelaczam na nia "
                "zamiast otwierac kolejna karte."
            )

            return _chrome_open_wynik(
                _juz,
                url,
                czekalismy=_czekalismy,
                juz_otwarta=True,
                message=(
                    "Ta strona juz byla otwarta w karcie "
                    + str(_juz["id"]) + " — przelaczylem na nia, "
                    "zamiast otwierac druga taka sama."
                )
            )

    global CDP_403

    # Jeżeli Chrome wcześniej odrzucił WebSocket 403,
    # nie próbujemy ponownie tego samego mechanizmu.
    if CDP_403:

        return {
            "ok": False,
            "error":
                "CDP wcześniej zwróciło 403. "
                "Użyj Androida do obsługi Chrome."
        }

    tab = find_tab(
        tab_id,
        contains
    )

    # WAŻNE:
    # NIE TWORZYMY NOWEJ KARTY przez CDP (/json/new nie jest
    # używane — patrz komentarz przy CDP_403). Ale zamiast od razu
    # poddawać się, gdy nie ma pasującej karty CDP, próbujemy
    # NATYWNEJ drogi Androida (am start -a VIEW -d <url>) — to
    # dokładnie ta sama komenda, którą MAIN_PROMPT każe zespołowi
    # wykonać RĘCZNIE jako obejście; robimy to tu automatycznie, bo
    # zaobserwowany realny problem to zespół WIEDZĄCY o tym
    # obejściu, ale nie wykonujący go konsekwentnie za każdym razem
    # (chrome_open zawodził 4x pod rząd zamiast raz przełączyć się
    # na am start).
    #
    # KRYTYCZNE — zaobserwowany realny incydent: goły `am start -a
    # VIEW -d <url>` BEZ pakietu pozwala Androidowi wybrać DOWOLNĄ
    # aplikację obsługującą ten intent — na tym urządzeniu czasem
    # otworzył Firefoksa zamiast Chrome. CDP jest podłączone
    # WYŁĄCZNIE do Chrome (adb forward tcp:9222), więc karta otwarta
    # w innej przeglądarce jest dla chrome_tabs() całkowicie
    # niewidoczna, niezależnie od tego, ile razy spróbujemy. Wymuszamy
    # więc pakiet Chrome (-p com.android.chrome); jeśli akurat go nie
    # ma na tym urządzeniu (inny build/wariant Chrome), próbujemy
    # jeszcze raz bez wymuszenia pakietu jako ostatniej deski ratunku.
    if tab is None:

        # v367: ZANIM ZROBIMY NOWA KARTE — sprawdzamy jeszcze raz.
        #
        # Wyzej pytalismy o to tylko wtedy, gdy nikt nie podal
        # tab_id. W biegu 2026-09-17 16:42 ostatnie wywolanie podalo
        # tab_id=1307, ta karta juz nie pokazywala tej strony, wiec
        # dedup zostal pominiety i `am start` zrobil karte 1311 —
        # choc ten sam adres wisial obok. Ten sam mechanizm
        # (_karta_z_tym_adresem), tylko pytany takze tutaj, w
        # ostatniej chwili przed utworzeniem duplikatu.
        _juz = _karta_z_tym_adresem(url)

        if _juz is not None:

            _przelacz_na_karte(_juz["id"])
            _czekalismy = _poczekaj_az_strona_dojdzie(_juz)

            log(
                "CHROME",
                "Podana karta juz nie pokazuje tej strony, ale inna "
                "tak (" + str(_juz["id"]) + ") — przelaczam sie na "
                "nia zamiast otwierac duplikat."
            )

            return _chrome_open_wynik(
                _juz,
                url,
                czekalismy=_czekalismy,
                juz_otwarta=True,
                message=(
                    "Ta strona juz byla otwarta w karcie "
                    + str(_juz["id"]) + " — przelaczylem na nia, "
                    "zamiast otwierac druga taka sama."
                )
            )

        fallback = execute_shell(
            "am start -a android.intent.action.VIEW -p "
            "com.android.chrome -d "
            + shlex.quote(str(url))
        )

        if not fallback.get("ok"):

            fallback = execute_shell(
                "am start -a android.intent.action.VIEW -d "
                + shlex.quote(str(url))
            )

        if not fallback.get("ok"):

            return {
                "ok": False,
                "error": (
                    "Nie znaleziono istniejącej karty CDP, a "
                    "próba otwarcia przez 'am start' też się nie "
                    "powiodła: "
                    + str(fallback.get("error", fallback))
                ),
                "fallback_attempted": "am_start"
            }

        # Sztywne 2 s wystarczaly na SAMO otwarcie karty, ale nie na
        # to, zeby strona sie narysowala. Karta pojawia sie od razu, a
        # dashboard w Reakcie potrzebuje jeszcze chwili; kto zajrzy w
        # ta chwile, zobaczy "Loading...". Czekamy wiec na karte, a
        # potem na sama strone — dokladnie tyle, ile trzeba.
        time.sleep(1.0)

        domain = ""

        try:
            domain = urlparse(str(url)).netloc
        except Exception:
            pass

        # v367: NAJPIERW karta z TYM adresem, dopiero potem
        # jakakolwiek z tej domeny.
        #
        # Bylo: find_tab(None, domain) — czyli PIERWSZA karta z tej
        # domeny. Gdy na dashboard.daily.co wisiala juz karta
        # /login, a wlasnie otwierali smy /rooms, dostawalismy z
        # powrotem /login i jego tresc. Nawigacja sie udala, a
        # odpowiedz mowila o zupelnie innej stronie — stad
        # "przeciez otworzylem, a widze stare".
        tab = (
            _karta_z_tym_adresem(url)
            or find_tab(None, domain or None)
            or find_tab(None, None)
        )

        if tab is None:

            return {
                "ok": False,
                "error": (
                    "Wysłano intencję 'am start' dla adresu, ale "
                    "nadal brak widocznej karty CDP (domyślna "
                    "przeglądarka mogła nie być Chrome, albo CDP "
                    "jeszcze nie zaindeksowało nowej karty — "
                    "sprawdź android_state, żeby potwierdzić, co "
                    "faktycznie jest na ekranie)."
                ),
                "fallback_attempted": "am_start"
            }

        _czekalismy = _poczekaj_az_strona_dojdzie(tab)

        try:
            tab = find_tab(tab["id"], None) or tab
        except Exception:
            pass

        return _chrome_open_wynik(
            tab,
            url,
            czekalismy=_czekalismy,
            metoda="am_start_fallback",
            nowa_karta=True
        )

    ws = cdp_connect(tab)

    if ws is None:

        return {
            "ok": False,
            "error": "CDP niedostępne"
        }

    try:

        result = cdp_call(
            ws,
            1,
            "Page.navigate",
            {
                "url": str(url)
            },
            timeout=20
        )

    finally:

        try:
            ws.close()
        except Exception:
            pass

    # Zamiast sztywnych 1,5 s — czekamy dokladnie tyle, ile ta strona
    # potrzebuje. Patrz _poczekaj_az_strona_dojdzie().
    _czekalismy = _poczekaj_az_strona_dojdzie(tab)

    if not result.get("ok", False):

        return {
            "ok": False,
            "tab_id": tab["id"],
            "url": str(url),
            "error": "Page.navigate nie powiodlo sie"
        }

    return _chrome_open_wynik(
        tab,
        url,
        czekalismy=_czekalismy
    )


# ============================================================
# CHROME CLICK
# ============================================================

def _stan_strony(tab):
    """
    Adres, tytul i dlugosc tresci — tyle, zeby powiedziec, CZY cos
    sie na stronie stalo. Zwraca None, gdy nie da sie odczytac.
    """

    try:

        stan = chrome_eval(
            tab,
            "(() => ({"
            " href: location.href,"
            " title: document.title,"
            " znakow: (document.body ?"
            " document.body.innerText.replace(/\\s+/g, ' ')"
            ".trim().length : 0)"
            "}))()"
        )

        if isinstance(stan, dict) and stan.get("href") is not None:
            return {
                "href": stan.get("href"),
                "title": stan.get("title"),
                "znakow": stan.get("znakow")
            }

    except Exception:
        pass

    return None


def chrome_click(
    text,
    tab_id=None,
    contains=None
):

    tab = find_tab(
        tab_id,
        contains
    )

    if tab is None:

        return {
            "ok": False,
            "error":
                "Brak istniejącej karty"
        }

    # Klikniecie w strone, ktora sie jeszcze rysuje, trafia w pustke
    # albo w nie ten element — patrz _poczekaj_az_strona_dojdzie().
    _czekalismy = _poczekaj_az_strona_dojdzie(tab)

    target = json.dumps(
        str(text),
        ensure_ascii=False
    )

    javascript = f"""
(() => {{

    const target =
        {target}.toLowerCase();

    const clean = (v) =>
        (v || "")
        .replace(/\\s+/g, " ")
        .trim();

    const elements =
        Array.from(
            document.querySelectorAll(
                'a,button,input,' +
                '[role="button"]'
            )
        );

    const el =
        elements.find(
            e =>
                clean(
                    e.innerText ||
                    e.value ||
                    e.getAttribute(
                        "aria-label"
                    )
                )
                .toLowerCase()
                .includes(target)
        );

    if (!el) {{

        return {{
            ok: false,
            error:
                "Nie znaleziono: " +
                {target}
        }};

    }}

    el.scrollIntoView({{
        block: "center"
    }});

    el.click();

    return {{
        ok: true,
        clicked:
            clean(
                el.innerText ||
                el.value ||
                el.getAttribute(
                    "aria-label"
                )
            )
    }};

}})()
"""

    # v366: KLIKNIECIE MA POWIEDZIEC, CZY COS SIE STALO.
    #
    # ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-17 16:42, krok 3).
    # Gemini probowalo kliknac "Log in with Google" JEDENASCIE razy
    # z rzedu — raz przez chrome_click, dziesiec razy przez wlasny
    # JavaScript (`el.click()`, `dispatchEvent`, szukanie po
    # `textContent`, po `outerHTML`, wywolanie reactowego onClick).
    # Po KAZDEJ probie pytalo osobnym wywolaniem o
    # `window.location.href` i za kazdym razem dostawalo to samo:
    #
    #     https://dashboard.daily.co/login
    #
    # Bo chrome_click odpowiadalo {"ok": true, "clicked": "Log in
    # with Google"} niezaleznie od tego, czy klikniecie cokolwiek
    # zrobilo. To byla prawda o WYSLANIU zdarzenia, a nie o jego
    # SKUTKU — a Gemini potrzebowalo tego drugiego, wiec dopisywalo
    # sobie sonde po kazdej probie.
    #
    # Nie uczymy Gemini, jak ma klikac. Mowimy mu, co sie stalo:
    # patrzymy na adres, tytul i dlugosc tekstu przed i po, i
    # dokladamy to do odpowiedzi. Gdy nic sie nie ruszylo, mowimy to
    # wprost — jednym zdaniem, zamiast zostawiac "ok: true".
    _przed = _stan_strony(tab)

    wynik = chrome_eval(
        tab,
        javascript
    )

    if not isinstance(wynik, dict) or not wynik.get("clicked"):
        return wynik

    # Reakcja strony nie jest natychmiastowa — to samo czekanie, co
    # przed kliknieciem (patrz _poczekaj_az_strona_dojdzie).
    _poczekaj_az_strona_dojdzie(tab)

    _po = _stan_strony(tab)

    if not _przed or not _po:
        return wynik

    _co_sie_zmienilo = []

    if _przed.get("href") != _po.get("href"):
        _co_sie_zmienilo.append(
            "adres: " + str(_przed.get("href"))
            + " -> " + str(_po.get("href"))
        )

    if _przed.get("title") != _po.get("title"):
        _co_sie_zmienilo.append(
            "tytul: " + str(_przed.get("title"))
            + " -> " + str(_po.get("title"))
        )

    _roznica = abs(
        int(_po.get("znakow") or 0)
        - int(_przed.get("znakow") or 0)
    )

    # Kilka znakow to zwykle licznik albo animacja, nie nowa tresc.
    if _roznica > 40:
        _co_sie_zmienilo.append(
            "tresc strony: " + str(_przed.get("znakow"))
            + " -> " + str(_po.get("znakow")) + " znakow"
        )

    wynik["adres"] = _po.get("href")

    if _co_sie_zmienilo:

        wynik["po_klknieciu"] = "; ".join(_co_sie_zmienilo)

    else:

        wynik["bez_skutku"] = True
        wynik["po_klknieciu"] = (
            "Kliknalem w ten element, ale strona sie nie ruszyla: "
            "adres, tytul i dlugosc tresci sa takie same jak przed "
            "kliknieciem. Samo powtorzenie tego kliknięcia nic nie "
            "zmieni. Zobacz chrome_inspect — pokazuje, co na tej "
            "stronie da sie kliknac i wypelnic."
        )

    # v377: STAN STRONY PO KLIKNIECIU — tak samo, jak
    # chrome_execute_js robi to od v373. Zadnej nowej sondy nie ma:
    # _po jest zmierzone wyzej, na potrzeby pomiaru skutku z v366.
    # Dzieki temu wspolny rdzen TARGET_STATE widzi cel (adres) i stan
    # (tytul, dlugosc tresci) tego klikniecia — i stad mogl zniknac
    # osobny licznik przegladarki z v367.
    wynik["tytul"] = _po.get("title")
    wynik["znakow"] = _po.get("znakow")

    # v367: to samo, co chrome_open — jeden spojny stan i pamiec o
    # tym, co juz probowalismy. Sam pomiar skutku z v366 zostaje
    # wyzej bez zmian.
    _zmienilo = _chrome_stan_sie_zmienil(_przed, _po)

    wynik["state_changed"] = bool(_zmienilo)

    _snap = _chrome_snapshot(
        tab,
        akcja="click " + short(str(text), 60),
        stan=_po,
        tresc=(_tresc_strony(tab) if not _zmienilo else None)
    )

    if _snap:
        wynik["snapshot"] = _snap

    _zaloguj_operacje_chrome(
        "click " + short(str(text), 60),
        _przed,
        _po,
        _zmienilo
    )

    return wynik


# ============================================================
# CHROME TYPE
# ============================================================

def chrome_type(
    text,
    tab_id=None,
    contains=None
):

    tab = find_tab(
        tab_id,
        contains
    )

    if tab is None:

        return {
            "ok": False,
            "error":
                "Brak istniejącej karty"
        }

    value = json.dumps(
        str(text),
        ensure_ascii=False
    )

    javascript = f"""
(() => {{

    const value =
        {value};

    const el =
        document.activeElement;

    if (!el) {{
        return {{
            ok: false,
            error:
                "Brak aktywnego elementu"
        }};
    }}

    const tag =
        el.tagName.toLowerCase();

    if (
        tag !== "input" &&
        tag !== "textarea" &&
        !el.isContentEditable
    ) {{

        return {{
            ok: false,
            error:
                "Aktywny element nie jest polem"
        }};

    }}

    if (
        el.isContentEditable
    ) {{

        el.textContent =
            value;

    }} else {{

        el.focus();
        el.value =
            value;

    }}

    el.dispatchEvent(
        new Event(
            "input",
            {{
                bubbles: true
            }}
        )
    );

    el.dispatchEvent(
        new Event(
            "change",
            {{
                bubbles: true
            }}
        )
    );

    return {{
        ok: true
    }};

}})()
"""

    return (
        chrome_eval(
            tab,
            javascript
        )
        or {
            "ok": False,
            "error": "Brak wyniku"
        }
    )


# ============================================================
# CHROME EXECUTE JS
# ============================================================
#
# Zaobserwowany realny problem (log 2026-08-26, cel: połączenie
# głosowe przez Vapi Dashboard): zespół POPRAWNIE zdiagnozował, że
# chrome_inspect() tylko CZYTA DOM i nie wykonuje JavaScriptu, i
# POPRAWNIE napisał kod (fetch() do API Vapi z "credentials:
# 'include'", korzystający z sesji przeglądarki, w którą użytkownik
# WŁAŚNIE się zalogował) — ale w całym zestawie narzędzi nie było
# NIC, co pozwoliłoby ten kod faktycznie wykonać. Zamiast tego zespół
# kliknął przypadkowy przycisk demo ("Test Talk to my agent" — to
# wbudowana funkcja Vapi do testowania asystenta przez mikrofon w
# przeglądarce, NIE prawdziwe połączenie wychodzące) i zgłosił to
# jako dowód sukcesu — CRITIC to poprawnie zablokował za każdym
# razem, ale zespół nie miał ŻADNEJ innej drogi do przodu, więc
# wracał do tego samego, błędnego działania w kółko.
#
# chrome_eval() (mechanizm CDP "Runtime.evaluate") już od dawna
# istniał w kodzie i jest używany WEWNĘTRZNIE przez chrome_click/
# chrome_type — ale nigdy nie był wystawiony Gemini jako osobne,
# ogólne narzędzie z DOWOLNYM kodem JS. To domyka lukę: Gemini może
# teraz faktycznie wykonać fetch()/XHR w kontekście zalogowanej
# karty (z prawdziwymi ciasteczkami sesji), zamiast pisać taki kod
# do pliku, którego i tak nic nie uruchomi.

def _detect_empty_js_fields(value):
    """
    v185 — zaobserwowany realny problem (log 2026-08-30, cel "Neat"):
    zespół wielokrotnie zakładał, że na stronie istnieją pola "host"/
    "input_area", mimo że chrome_execute_js WPROST zwrócił dla nich
    identyczną wartość-zaślepkę ("BRAK") dla obu — czyli selektor JS
    nie trafił w ŻADEN prawdziwy element. To nie zostało wystarczająco
    mocno podkreślone: informacja utonęła w kolejnych akapitach prozy
    i zespół zrobił jeszcze jedną pełną rundę tej samej hipotezy.

    Nie zgadujemy KONKRETNEGO słowa-zaślepki (mogło być "BRAK", "null",
    "N/A", cokolwiek — to zależy od JS, które napisał zespół) — zamiast
    tego wykrywamy WZORZEC: kilka RÓŻNIE nazwanych kluczy zwraca
    IDENTYCZNĄ, krótką wartość (albo puste/None). To silny sygnał
    "selektor nic nie znalazł", niezależnie od użytego słowa.
    Ignorujemy długie wartości (np. treść strony) — to zwykle
    faktycznie pobrana treść, nie zaślepka.
    """

    if not isinstance(value, dict) or len(value) < 2:
        return None

    sentinel_like = {}

    for key, val in value.items():
        if val is None:
            sentinel_like[key] = ""
        elif isinstance(val, str) and len(val) <= 20:
            sentinel_like[key] = val

    if len(sentinel_like) < 2:
        return None

    counts = {}
    for val in sentinel_like.values():
        counts[val] = counts.get(val, 0) + 1

    repeated_value, repeated_count = max(
        counts.items(), key=lambda item: item[1]
    )

    if repeated_count < 2:
        return None

    repeated_keys = [
        k for k, v in sentinel_like.items() if v == repeated_value
    ]

    return (
        "UWAGA: pola " + ", ".join(repeated_keys) + " zwrócone przez "
        "ten skrypt JS mają IDENTYCZNĄ, pustą/zaślepkową wartość ("
        + repr(repeated_value) + ") — to silny sygnał, że selektor "
        "nie trafił w ŻADEN prawdziwy element na tej stronie, a NIE że "
        "dane akurat są puste. Nie zakładaj dalej, że te konkretne pola "
        "istnieją na tym ekranie — sprawdź inny adres/kartę, albo "
        "poproś o inny, niezależny dowód, zamiast ponawiać tę samą "
        "hipotezę."
    )


def chrome_execute_js(
    javascript,
    tab_id=None,
    contains=None
):
    """
    Zaobserwowany realny problem (log 2026-08-27, cel: klucz API
    Bland AI): Gemini po utworzeniu nowego klucza próbował go odczytać
    przez coś na wzór navigator.clipboard.readText() (strona pokazywała
    "API key copied to clipboard") — ale odczyt schowka przeglądarki
    wymaga zgody użytkownika w oknie, którego NIKT (żaden proces) nie
    może kliknąć w tej sesji CDP. Wywołanie wisiało pełne 20 sekund
    (domyślny timeout cdp_call) i kończyło się "Connection timed out",
    po czym zespół, zamiast spróbować odczytać wartość WPROST Z DOM-u
    (np. z pola/input/modału, w którym nowy klucz jest widoczny w
    postaci jawnego tekstu ZANIM zniknie po jego "skopiowaniu"),
    poddawał się i pytał człowieka.

    Krótszy timeout (10s zamiast domyślnych 20s dla chrome_click/
    chrome_type/chrome_inspect, które używają wyłącznie szybkich,
    znanych operacji DOM) sprawia, że taka sytuacja kończy się
    szybciej i jaśniejszym błędem, zamiast marnować pół minuty na
    każdą próbę.
    """

    tab = find_tab(
        tab_id,
        contains
    )

    if tab is None:

        return {
            "ok": False,
            "error":
                "Brak istniejącej karty"
        }

    # Ten sam powod co przy chrome_click i chrome_inspect: kod
    # puszczony na strone, ktora sie jeszcze rysuje, nie znajdzie
    # elementow, ktore za pol sekundy tam beda. Patrz
    # _poczekaj_az_strona_dojdzie() — dla gotowej strony to kosztuje
    # zero.
    _czekalismy = _poczekaj_az_strona_dojdzie(tab)

    result = chrome_eval(
        tab,
        javascript,
        timeout=10
    )

    if (
        isinstance(result, dict)
        and result.get("ok") is False
    ):
        return result

    dom_fields_warning = _detect_empty_js_fields(result)

    final = {
        "ok": True,
        "value": result
    }

    if _czekalismy:
        final["czekalem_na_zaladowanie_s"] = _czekalismy

    if dom_fields_warning:
        final["dom_fields_warning"] = dom_fields_warning

    # v373: STAN STRONY PO TYM JS — tym samym snapshotem, ktorego
    # uzywa chrome_click od v366. Nie powstaje zadna nowa sonda: to
    # jest _stan_strony(), jedno lekkie pytanie o adres, tytul i
    # dlugosc tresci.
    #
    # Po co: wynik chrome_execute_js to bylo dotad samo {"ok": true,
    # "value": ...}. "value" mowi, co zwrocil JavaScript, a nie co
    # zrobil ze strona.
    #
    # ZAOBSERWOWANY REALNY PRZYPADEK (bieg 2026-09-17 16:42, krok 3).
    # Gemini probowalo kliknac "Log in with Google" jedenascie razy,
    # za kazdym razem innym kodem: el.click(), dispatchEvent(),
    # szukanie po textContent, po outerHTML, reactowy onClick,
    # getBoundingClientRect. "value" bylo za kazdym razem INNE
    # ("clicked", "clicked via button text", "clicked element with
    # exact text", "not found"...), wiec po samym "value" kazda proba
    # wygladala na nowa droge. Strona przez caly czas byla ta sama:
    # https://dashboard.daily.co/login.
    #
    # Dlatego stanem celu jest STRONA, a nie to, co zwrocil JS.
    # Adres trafia do wyniku jako "url" — po nim wspolny rdzen z
    # v372 rozpoznaje cel (_cel_wywolania), a po tytule i dlugosci
    # tresci widzi, czy cokolwiek drgnelo (_stan_celu).
    _po = _stan_strony(tab)

    if _po:

        if _po.get("href"):
            final["url"] = _po.get("href")

        final["tytul"] = _po.get("title")
        final["znakow"] = _po.get("znakow")

    return final


# ============================================================
# GEMINI KEYS
# ============================================================

def load_gemini_keys():

    keys = []

    main = read_text(
        GEMINI_KEY_FILE
    ).strip()

    if main:
        keys.append(
            ("main", main)
        )

    for path in sorted(
        GEMINI_KEYS_DIR.glob("*.txt")
    ):

        value = read_text(
            path
        ).strip()

        if value:

            if not any(
                key == value
                for _, key in keys
            ):

                keys.append(
                    (
                        path.name,
                        value
                    )
                )

    env = os.environ.get(
        "GEMINI_API_KEY",
        ""
    ).strip()

    if env:

        if not any(
            key == env
            for _, key in keys
        ):

            keys.append(
                ("environment", env)
            )

    return keys


# ============================================================
# WYCZERPANY KLUCZ GEMINI WRACA DO GRY (v277)
# ============================================================
#
# Byly tu dwa bledy wskazujace w PRZECIWNE strony, ktore sie
# nawzajem maskowaly — dlatego nigdy nie bylo tego widac w logu
# jako jednej awarii.
#
# 1. mark_quota() zapisywalo "ten klucz padl" do gemini.json, ale
#    KAZDA udana interakcja z Gemini nadpisywala ten sam plik
#    w calosci ({"task_id": ..., "interaction_id": ...}). write_json
#    nadpisuje, nie doklada. Wiedza o wyczerpanym kluczu znikala
#    wiec po jednym wywolaniu i agent wracal do martwego klucza:
#    429, przelaczenie, zapomnienie, znowu 429.
#
# 2. W druga strone: key_disabled() czytalo tylko "status", a pole
#    "time" nie bylo czytane NIGDZIE. Gdyby wpis jednak przetrwal,
#    klucz bylby martwy na zawsze — mimo ze limit Gemini sie
#    odnawia. Wskrzeszal go dopiero "wyczysc".
#
# Teraz: stan kluczy ma wlasny plik, a "time" jest czytane. Odstep
# rosnie tak samo, jak przy przeciazeniu DeepSeeka (v268): pierwszy
# raz krotko, bo 429 to zwykle limit na minute; gdy ten sam klucz
# pada zaraz po powrocie, to znaczy, ze to limit dzienny — wtedy
# podwajamy, zeby nie dobijac sie co chwile. Udane wywolanie
# kasuje wpis.
_GEMINI_COOLDOWN_START = 60.0
_GEMINI_COOLDOWN_MAX = 6 * 3600.0


def gemini_keys_state():

    value = read_json(
        GEMINI_KEYS_FILE,
        {}
    )

    if not isinstance(value, dict):
        return {}

    return value


def save_gemini_keys_state(value):

    write_json(
        GEMINI_KEYS_FILE,
        value
    )


def mark_quota(key_name):

    state = gemini_keys_state()

    poprzedni = state.get(str(key_name)) or {}

    try:
        byl_odstep = float(poprzedni.get("cooldown") or 0.0)
        byl_kiedy = float(poprzedni.get("time") or 0.0)
    except (TypeError, ValueError):
        byl_odstep, byl_kiedy = 0.0, 0.0

    # Padl znowu tuz po tym, jak wrocil do gry — poprzedni odstep
    # byl za krotki.
    if byl_odstep and (time.time() - byl_kiedy) < byl_odstep * 3:
        odstep = min(byl_odstep * 2, _GEMINI_COOLDOWN_MAX)
    else:
        odstep = _GEMINI_COOLDOWN_START

    state[str(key_name)] = {
        "status": "QUOTA_EXHAUSTED",
        "time": time.time(),
        "cooldown": odstep
    }

    save_gemini_keys_state(state)

    log(
        "GEMINI",
        "Klucz " + str(key_name) + " odstawiony na "
        + str(int(odstep // 60)) + " min — potem sam wroci do gry."
    )


def mark_key_ok(key_name):
    """Klucz odpowiedzial — nie ma powodu go dalej omijac."""

    state = gemini_keys_state()

    if str(key_name) in state:

        del state[str(key_name)]

        save_gemini_keys_state(state)

        log(
            "GEMINI",
            "Klucz " + str(key_name) + " znowu odpowiada — "
            "wraca do normalnego uzycia."
        )


def key_disabled(key_name):

    info = gemini_keys_state().get(str(key_name))

    if not info:
        return False

    if info.get("status") != "QUOTA_EXHAUSTED":
        return False

    try:
        czekaj = float(info.get("cooldown") or _GEMINI_COOLDOWN_START)
        kiedy = float(info.get("time") or 0.0)
    except (TypeError, ValueError):
        return False

    return (time.time() - kiedy) < czekaj


def init_gemini():

    global gemini_clients

    if not GEMINI_LIBRARY_OK:
        return False

    keys = load_gemini_keys()

    if not keys:

        log(
            "GEMINI",
            "Brak klucza API"
        )

        return False

    for name, key in keys:

        if key_disabled(name):
            continue

        try:

            client = genai.Client(
                api_key=key
            )

            gemini_clients[
                name
            ] = client

            log(
                "GEMINI",
                "Klucz dostępny: "
                + name
            )

        except Exception as e:

            log(
                "GEMINI",
                f"{name}: {e}"
            )

    if gemini_clients:

        log(
            "GEMINI",
            "API OK — "
            + GEMINI_MODEL
        )

        return True

    log(
        "GEMINI",
        "Brak aktywnych kluczy"
    )

    return False


def get_gemini_client():

    for name, _ in load_gemini_keys():

        if key_disabled(name):
            continue

        client = gemini_clients.get(
            name
        )

        if client is not None:
            return name, client

    return None, None


